window.ScripturaLexicons.BDAG_PART_0290 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-01\" data-source=\"BDAG\" data-search=\"πλόος substantivo masculino viagem, navegação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλόος</td><td>substantivo masculino</td><td>viagem, navegação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-02\" data-source=\"BDAG\" data-search=\"πλούσιος, ία, ιον adjetivo rico, abastado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλούσιος, ία, ιον</td><td>adjetivo</td><td>rico, abastado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-03\" data-source=\"BDAG\" data-search=\"πλουσίως advérbio ricamente, abundantemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλουσίως</td><td>advérbio</td><td>ricamente, abundantemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-04\" data-source=\"BDAG\" data-search=\"πλουτέω verbo ser rico, enriquecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλουτέω</td><td>verbo</td><td>ser rico, enriquecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-05\" data-source=\"BDAG\" data-search=\"πλουτίζω verbo enriquecer, tornar rico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλουτίζω</td><td>verbo</td><td>enriquecer, tornar rico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-06\" data-source=\"BDAG\" data-search=\"πλοῦτος, ου, ὁ substantivo masculino riqueza, abundância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλοῦτος, ου, ὁ</td><td>substantivo masculino</td><td>riqueza, abundância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-07\" data-source=\"BDAG\" data-search=\"πλύνω verbo lavar, purificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλύνω</td><td>verbo</td><td>lavar, purificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-08\" data-source=\"BDAG\" data-search=\"πνεῦμα, ατος, τό substantivo neutro vento, sopro, espírito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνεῦμα, ατος, τό</td><td>substantivo neutro</td><td>vento, sopro, espírito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-09\" data-source=\"BDAG\" data-search=\"πνευματικός, ή, όν adjetivo espiritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνευματικός, ή, όν</td><td>adjetivo</td><td>espiritual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-10\" data-source=\"BDAG\" data-search=\"πνευματικῶς advérbio espiritualmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνευματικῶς</td><td>advérbio</td><td>espiritualmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-11\" data-source=\"BDAG\" data-search=\"πνευματοφόρος, ον adjetivo portador do Espírito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνευματοφόρος, ον</td><td>adjetivo</td><td>portador do Espírito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-12\" data-source=\"BDAG\" data-search=\"πνέω verbo soprar, exalar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνέω</td><td>verbo</td><td>soprar, exalar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-13\" data-source=\"BDAG\" data-search=\"πνίγω verbo estrangular, sufocar, afogar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνίγω</td><td>verbo</td><td>estrangular, sufocar, afogar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-14\" data-source=\"BDAG\" data-search=\"πνικτός, ή, όν adjetivo estrangulado, sufocado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνικτός, ή, όν</td><td>adjetivo</td><td>estrangulado, sufocado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-15\" data-source=\"BDAG\" data-search=\"πνοή, ῆς, ἡ substantivo feminino vento, sopro, respiração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πνοή, ῆς, ἡ</td><td>substantivo feminino</td><td>vento, sopro, respiração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-16\" data-source=\"BDAG\" data-search=\"ποδαπός remissão ver ποταπός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποδαπός</td><td>remissão</td><td>ver ποταπός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-17\" data-source=\"BDAG\" data-search=\"ποδήρης, ες adjetivo que chega aos pés, veste talar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποδήρης, ες</td><td>adjetivo</td><td>que chega aos pés, veste talar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-18\" data-source=\"BDAG\" data-search=\"ποδονιπτήρ, ῆρος, ὁ substantivo masculino bacia para lavar os pés BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποδονιπτήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>bacia para lavar os pés</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-19\" data-source=\"BDAG\" data-search=\"πόθεν advérbio interrogativo de onde, de que origem, como, por quê BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόθεν</td><td>advérbio interrogativo</td><td>de onde, de que origem, como, por quê</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0290-20\" data-source=\"BDAG\" data-search=\"ποθέω verbo ansiar, desejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποθέω</td><td>verbo</td><td>ansiar, desejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0290-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόος</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλόος</span> (Hom. et al.) ou, por contração, <span class=\"greek\">πλοῦς</span> (ático; ins, pap, Wsd 14:1; Philo, Joseph., Just.), <span class=\"greek\">ὁ</span>, originalmente pertencente à segunda declinação. Na época helenística passou à terceira declinação e é declinado como <span class=\"greek\">βοῦς</span> (v. B-D-F §52; W-S. §8, 11, fim; Mlt-H. 127; 142). Em nossa literatura a palavra se restringe a Ac, onde tem o gen. <span class=\"greek\">πλοός</span> (Peripl. Eryth. 61; Xenophon Eph. 1, 14; 5, 12; OGI 572, 21 [c. 200 d.C.]; mas <span class=\"greek\">πλοῦ</span> Just., D. 142, 3) e o ac. <span class=\"greek\">πλοῦν</span> (Jos., Bell. 2, 40, Ant. 8, 181; Just., D. 142, 1): deslocamento de uma embarcação pela água, viagem, navegação (assim Hom. et al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:9f</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">διανύειν</span> (v. <span class=\"greek\">διανύω</span> 1) 21:7. Também <span class=\"greek\">ἐτελέσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πλ</span>. AcPl Ha 7, 35.—DELG s.v. <span class=\"greek\">πλέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλούσιος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλούσιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (<span class=\"greek\">πλοῦτος</span>; Hes., Hdt.+)</p><p class=\"entry-text\">① Relativo à posse de uma abundância de bens terrenos que excede a experiência normal, rico, abastado, <span class=\"greek\">ἦν</span> <span class=\"greek\">Ἰωακεὶμ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">σφόδρα</span> GJs 1:1 (Sus 4 Theod.); <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">πλ</span>. um homem rico (isto é, alguém que não precisa trabalhar para subsistir) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:16</a>; cf. 16:1, 19 (aqui, em P75, o nome do rico é dado como <span class=\"greek\">Νευης</span>, v. o artigo separado); 18:23; 19:2. <span class=\"greek\">γείτονες</span> <span class=\"greek\">πλ</span>. vizinhos abastados 14:12.—Substantivado: <span class=\"greek\">ὁ</span> <span class=\"greek\">πλ</span>. o rico (frequentemente em contraste com o pobre; cf. TestAbr A 19 p. 101, 20, [Stone p. 50; oposto a <span class=\"greek\">πένης</span>, que precisa trabalhar para subsistir].—V. PFurfey, CBQ 5, ’43, 241–63) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:21f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:10f</a>; 1 Cl 13:1 (Jer 9:22); 38:2; Hs 2:5–7 (no v. 4 <span class=\"greek\">εἰς</span> <span class=\"greek\">πτωχὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλούσιον</span> o artigo é omitido depois da preposição). Pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">πλ</span>. (Menand., Cith. Fgm. 1, 1 Kö. [=Fgm. 281, 1]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:24</a>; 21:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:6</a>; 5:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:15</a>; 13:16; 1 Cl 16:10 (Is 53:9); Hs 2:8; 9, 20, 1f. Sem artigo, <span class=\"greek\">πλούσιος</span> um rico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:23f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:25</a> (cf. Sextus 193 <span class=\"greek\">χαλεπόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πλουτοῦντα</span> <span class=\"greek\">σωθῆναι</span>; v. também Pla., Laws 5, 743a). Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:41</a>; B 20:2; D 5:2.—Do Cristo preexistente: <span class=\"greek\">δι</span>’ <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐπτώχευσεν</span> <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ὤν</span> por vossa causa tornou-se destituído de recursos, embora fosse rico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:9</a> (aqui a ênfase na oposição riqueza/pobreza diz respeito especialmente à condição, cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:6</a>–11; alguns situam a passagem na acepção 2 abaixo; contraste com Demosth 18, 131).</p><p class=\"entry-text\">② Relativo a estar abundantemente provido de algo, abundar (em), rico (em), extensão figurada de 1 (Menand., Fgm. 936 Kö. e EpArist 15 <span class=\"greek\">πλουσία</span> <span class=\"greek\">ψυχή</span>; PsSol 5:14 <span class=\"greek\">δόμα</span> … <span class=\"greek\">πλούσιον</span>; CIG IV, 9688, 4f <span class=\"greek\">τέκνα</span>), rico <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> em algo, de Deus <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐλέει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:4</a>; de seres humanos <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:5</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> (análogo a <span class=\"greek\">πτωχὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:3</a>, mas não em contraste com ele) rico em espírito (em paralelo com <span class=\"greek\">ἁπλοῦ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδία</span>) B 19:2. Uso absoluto, daqueles que são ricos em sentido transcendente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:9</a>; 3:17; cf. (<span class=\"greek\">ἡ</span> <span class=\"greek\">ἔντευξίς</span> <span class=\"greek\">ἐστιν</span>) <span class=\"greek\">πλουσία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">κυρίον</span> Hs 2:6. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλουσίου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">κυρίου</span> da parte do Senhor, que é rico em amor B 1:3 (sobre o texto, talvez corrompido, v. Windisch, Hdb. ad loc.). O texto também é incerto no v. 2, onde <span class=\"greek\">μεγάλων</span> <span class=\"greek\">ὄντων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλουσίων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">δικαιωμάτων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> provavelmente deve ser traduzido: visto que os atos justos de Deus para convosco são grandes e generosos. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:9</a> v. 1 acima.—Para a bibliografia, v. <span class=\"greek\">πλοῦτος</span>, <span class=\"greek\">πτωχός</span>.—DELG s.v. <span class=\"greek\">πλοῦτος</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουσίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλουσίως</span>, adv. de <span class=\"greek\">πλούσιος</span> (desde Eur.; Hdt. 2, 44; OGI 767, 18; Philo), ricamente, abundantemente <span class=\"greek\">ἐκχέειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:6</a>. <span class=\"greek\">ἐνοικεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:16</a>. <span class=\"greek\">ἐπιχορηγεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:11</a>. <span class=\"greek\">μανθάνειν</span> B 9:7. <span class=\"greek\">παρέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>. Comparativo <span class=\"greek\">πλουσιώτερον</span> (X., Oec. 9, 13), mais ricamente, mais abundantemente (com <span class=\"greek\">ὑψηλότερον</span>) B 1:7.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλουτέω</span> fut. 3ª pess. sing. <span class=\"greek\">πλουτήσει</span> Da 11:2; 1º aor. <span class=\"greek\">ἐπλούτησα</span>; perf. <span class=\"greek\">πεπλούτηκα</span> (<span class=\"greek\">πλοῦτος</span>; Hes., Hdt. et al.; SIG 1268, 30; PGiss 13, 19; LXX, pseudepigr., Philo, Joseph., Tat.)</p><p class=\"entry-text\">① Estar relativamente alto numa escala de opulência, ser rico; no aor., tornar-se rico; no perf., ter-se tornado rico. Literalmente, em uso absoluto (Artem. 4, 59; En 97:8 <span class=\"greek\">πλούτῳ</span> <span class=\"greek\">πεπλουτήκαμεν</span>; ApcMos 24; Philo, Virt. 166; Jos., Ant. 4:14; Tat. 11:1; Orig., C. Cels. 8, 38, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:9</a>; 2 Cl 20:1; Dg 10:5; Hv 3, 6, 7; ApcPt 15:30. <span class=\"greek\">οἱ</span> <span class=\"greek\">πλουτοῦντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἰῶνι</span> aqueles que possuem riquezas nesta era Hv 3, 6, 6.—Aor. Hs 8, 9, 1. A fonte da qual provém a riqueza é indicada por <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Aristoph., Plut. 569; Lucian, Dial. Deor. 16, 1; Sir 11:18) <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔμποροι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πλουτήσαντες</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:15</a>. Também <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> (Lysias 32, 25) vv. 3, 19.</p><p class=\"entry-text\">② Estar abundantemente provido de algo, ser rico, em linguagem figurada, <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> em algo (Synes., Ep. 130 p. 265b; OdeSol 11:9) <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">καλοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:18</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐντεύξει</span> Hs 2:7. <span class=\"greek\">εἰς</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">πλ</span>. ser rico em Deus ou para com Deus, em todo caso, nas coisas que têm valor aos olhos de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:21</a>. A construção com <span class=\"greek\">εἰς</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:12</a> é diferente: <span class=\"greek\">κύριος</span> <span class=\"greek\">πλουτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πάντας</span> o Senhor, que é rico (e generoso) para com todos, isto é, que distribui generosamente a todos de sua riqueza (Philostrat., Vi. Apoll. 4, 8 p. 129, 16 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κοινόν</span>).—Uso absoluto, de ser rico em valores transcendentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:9</a> (<span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">πτωχείᾳ</span> é dat. de instrumento ou de causa); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>. Perf. <span class=\"greek\">πλούσιός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πεπλούτηκα</span> v. 17 (cf. também Hos 12:9).—DELG s.v. <span class=\"greek\">πλοῦτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλουτίζω</span> (<span class=\"greek\">πλοῦτος</span>) fut. 3ª pess. sing. <span class=\"greek\">πλουτίσει</span> 1 Km 17:25 Theod.(?) e inf. <span class=\"greek\">πλουτιεῖν</span> 2 Macc 7:24; 1º aor. <span class=\"greek\">ἐπλούτισα</span>. Pass.: 1º fut. 3ª pess. sing. <span class=\"greek\">πλουτισθήσεται</span> Sir 19:1; 1º aor. <span class=\"greek\">ἐπλουτίσθην</span> (Aeschyl., X. et al.; ins, LXX; Anz 297)</p><p class=\"entry-text\">① Fazer com que alguém esteja relativamente alto numa escala de opulência, tornar rico, <span class=\"greek\">τινά</span> alguém (Gen 14:23; Sir 11:21; Jos., Ant. 17, 147) Hs 1:9. Uso absoluto (com <span class=\"greek\">πτωχίζω</span>), de Deus 1 Cl 59:3 (cf. 1 Km 2:7). Pass. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">πλουτίζεσθαι</span> receber do Senhor as próprias riquezas Hs 2:10.</p><p class=\"entry-text\">② Fazer abundar em algo, enriquecer, em linguagem figurada, de riquezas espirituais: <span class=\"greek\">τινά</span> alguém, do apóstolo Paulo, ao qual somente provavelmente se refere o pl. em <span class=\"greek\">ὡς</span> <span class=\"greek\">πτωχοὶ</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">πλουτίζοντες</span> como pobres, embora enriquecendo a muitos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:10</a>; cf., dos cristãos, <span class=\"greek\">πτωχεύουσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλουτίζουσι</span> <span class=\"greek\">πολλούς</span> Dg 5:13. Pass. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span>, <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">πλουτίζεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> 11:5. <span class=\"greek\">πλουτίζεσθαι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> ser enriquecido em algo. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντί</span> em tudo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:5</a>; a expressão é retomada com <span class=\"greek\">ἐν</span> <span class=\"greek\">παντί</span> <span class=\"greek\">λόγῳ</span>, que lhe dá conteúdo. O <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> no mesmo versículo indica que essa rica posse depende de uma relação estreita com Cristo. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">πλουτιζόμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἀπλότητα</span> sendo enriquecidos de todas as maneiras para toda (demonstração de) generosidade, isto é, para que demonstreis generosidade de todas as maneiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:11</a>.—DELG s.v. <span class=\"greek\">πλοῦτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοῦτος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλοῦτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. os quatro artigos precedentes; Hom.+). Paulo, que também emprega o masc., em oito passagens (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:7</a>; 2:7; 3:8, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:27</a>; 2:2) apresenta no nom. e no ac. o neutro <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῦτος</span> (AcPh 109 [Aa II/2, 42, 5]; Is 29:2 [segundo SA; v. Thackeray 159]); Tdf., Proleg. 118; W-H., app. 158; B-D-F §51, 2; Mlt-H. 127; Gignac II 100; ‘riqueza, riquezas’.</p><p class=\"entry-text\">① Abundância de muitos bens terrenos, riqueza (Iren. 1, 8, 3 [Harv. I 71, 9]; Orig., C. Cels. 3, 9, 8; <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀνθρώπινα</span> Did., Gen. 150, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a>; 1 Cl 13:1 (Jer 9:22); Hv 3, 6, 5b; 6b; m 10, 1, 4; Hs 1:8; 2:5, 7f (<span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>.); ApcPt 15, 30. Desencaminhando almas Hv 3, 6, 6a (texto restaurado). <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span> 3, 6, 5a. <span class=\"greek\">πολυτέλεια</span> <span class=\"greek\">πλούτου</span> m 8:3; 12, 2, 1. <span class=\"greek\">γαυριᾶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλούτῳ</span> gloriar-se na riqueza 1, 1, 8. Também <span class=\"greek\">γαυροῦσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλ</span>. 3, 9, 6. <span class=\"greek\">ἐπιλάθου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλούτου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κάλλους</span> <span class=\"greek\">σου</span> AcPl Ha 2, 21; <span class=\"greek\">πλ</span>. <span class=\"greek\">καταναλίσκεται</span> 2, 24f; a restauração em 9, 9 baseia-se em 2:24f.—OSchilling, Reichtum u. Eigentum in der altkirchl. Lit. 1908 (p. ix–xii para bibliografia); ETroeltsch, D. Soziallehren der christl. Kirchen u. Gruppen 1912; MWeber, D. Wirtschaftsethik der Weltreligionen: Archiv f. Sozialwissensch. 44, 1918, 52ff; FHauck, Die Stellung des Urchristentums zu Arbeit u. Geld 1921; ELohmeyer, Soziale Fragen im Urchristentum 1921; HGreeven, D. Hauptproblem der Sozialethik in der neueren Stoa u. im Urchristentum ’35 (escravidão, propriedade, casamento); KBornhäuser, D. Christ u. s. Habe nach dem NT ’36; HvCampenhausen, D. Askese im Urchristentum ’49. Cf. <span class=\"greek\">πτωχός</span> 1.</p><p class=\"entry-text\">② Provisão abundante de algo, riqueza, abundância, extensão figurada de 1, com gen. de coisa (Pla., Euthyphr. 12a <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span>; Theoph. Ant. 2, 12 [p. 130, 6] <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁπλότητος</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:2</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:18</a>; 3:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:27</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πληροφορίας</span> 2:2. <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:7</a>; 2:7. <span class=\"greek\">τῆς</span> <span class=\"greek\">χρηστότητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:4</a> (Simplicius In Epict. p. 12, 7 <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αὐτοῦ</span> [Deus] <span class=\"greek\">ἀγαθότητος</span>). Os genitivos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:12</a>, <span class=\"greek\">πλ</span>. <span class=\"greek\">κόσμου</span>, <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐθνῶν</span>, são diferentes: abundância (de benefícios) para o mundo, para os gentios. Daquilo que Deus ou Cristo possui em abundância ilimitada: <span class=\"greek\">βάθος</span> <span class=\"greek\">πλούτου</span> v. 33 (v. <span class=\"greek\">βάθος</span> 2 e cf. Jos., Bell. 6, 442 <span class=\"greek\">ὁ</span> <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βαθύς</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:19</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:12</a> (com <span class=\"greek\">δύναμις</span>, <span class=\"greek\">σοφία</span>, <span class=\"greek\">ἰσχύς</span>, <span class=\"greek\">τιμή</span>, <span class=\"greek\">δόξα</span>, <span class=\"greek\">εὐλογία</span>. Cf. Aristot., Pol. 1323a, 37f <span class=\"greek\">πλοῦτος</span>, <span class=\"greek\">χρήματα</span>, <span class=\"greek\">δύναμις</span>, <span class=\"greek\">δόξα</span>; Herodas 1, 28 <span class=\"greek\">πλοῦτος</span>, <span class=\"greek\">δύναμις</span>, <span class=\"greek\">δόξα</span>; Crantor [IV/III a.C.]: FPhGr III 148 <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δόξα</span>; Diod S 4, 74, 1 <span class=\"greek\">πλ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">δόξα</span>).—<span class=\"greek\">μείζονα</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἡγησάμενος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Αἰγύπτου</span> <span class=\"greek\">θησαυρῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀνειδισμὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> considerou o opróbrio sofrido por causa do Cristo uma riqueza maior do que os tesouros do Egito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:26</a>.—TESchmidt, Hostility to Wealth in Philo of Alexandria: JSNT 19, ’83, 85–97; para outra bibliografia, v. <span class=\"greek\">πένης</span>. B. 772. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλύνω</span> imperf. <span class=\"greek\">ἔπλυνον</span>; fut. <span class=\"greek\">πλυνῶ</span>; 1º aor. <span class=\"greek\">ἔπλυνα</span>, imperat. <span class=\"greek\">πλῦνον</span>. Pass.: fut. 3ª pess. sing. <span class=\"greek\">πλυθήσεται</span> LXX; inf. aor. <span class=\"greek\">πλυθῆναι</span> Lev 13:55 (Hom. et al.; OGI 483, 169 <span class=\"greek\">ἱμάτια</span>; PStras 91, 8; PSI 599, 7; PLond V, 1695, 18; LXX; TestSol 18:15; TestAbr B 6 p. 110, 24 [Stone p. 68]; Philo, Leg. All. 3, 144; 147; Just.)</p><p class=\"entry-text\">① Lavar algo que não seja parte do corpo (para esta, v. <span class=\"greek\">λούω</span> 1b), lavar. <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκτυα</span> lavar as redes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:2</a> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:19</a> <span class=\"greek\">καταρτίζειν</span> ‘consertar’). Lavagem de vestes (Artem. 2, 3 p. 88, 23) como símbolo de purificação dos pecados, <span class=\"greek\">ἔπλυναν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">στολὰς</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:14</a> (sobre <span class=\"greek\">πλύνειν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στολ</span>., por vezes com <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, cf. Gen 49:11.—Appian, Samn. 7 §6, de uma veste contaminada, <span class=\"greek\">ἐκπλυνεῖτε</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">πολλῷ</span>=lavareis isto com muito sangue); cf. 22:14. Isso proporciona uma transição fácil para</p><p class=\"entry-text\">② Livrar algo de algo, livrar de, isto é, da impureza do pecado; extensão figurada de 1, embora ainda se perceba o sentido original de <span class=\"greek\">πλ</span>. (cf. Artem. 2, 4) <span class=\"greek\">πλῦνόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span> <span class=\"greek\">μου</span> 1 Cl 18:3 (Ps 50:4) e, na continuação da citação, <span class=\"greek\">πλυνεῖς</span> <span class=\"greek\">με</span> v. 7 (Ps 50:9).—B. 579. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνεῦμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνεῦμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πνέω</span>; Aeschyl., Pre-Socr., Hdt.+. Sobre a história da palavra, v. Rtzst., Mysterienrel.3 308ff).</p><p class=\"entry-text\">① Ar em movimento, sopro, respiração (até mesmo as exalações incandescentes de uma cratera vulcânica: Diod S 5, 7, 3).</p><p class=\"entry-text\">ⓐ Vento (Aeschyl. et al.; LXX, EpArist, Philo; Jos., Ant. 2, 343; 349; SibOr 8, 297), em jogo de palavras <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πνεῖ</span> o vento sopra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8a</a> (EpJer 60 <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">χώρᾳ</span> <span class=\"greek\">πνεῖ</span>. Mas v. TDonn, ET 66, ’54f, 32; JThomas, Restoration Qtrly 24, ’81, 219–24). <span class=\"greek\">ὀθόνη</span> <span class=\"greek\">πλοίου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πληρουμένη</span> MPol 15:2. De Deus: <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιῶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀγγέλους</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πνεύματα</span> aquele que faz de seus anjos ventos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7</a>; 1 Cl 36:3 (ambos Ps 103:4).</p><p class=\"entry-text\">ⓑ Expiração de ar, sopro, hálito (Aeschyl. et al.; Pla., Tim. 79b; LXX) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνομος</span>, <span class=\"greek\">ὅν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἀνελεῖ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:8</a> (cf. Is 11:4; Ps 32:6).</p><p class=\"entry-text\">② Aquilo que anima ou dá vida ao corpo, alento, espírito (vital) (Aeschyl. et al.; Phoenix of Colophon 1, 16 [Coll. Alex. p. 231] <span class=\"greek\">πν</span>.=um ser que respira [em contraste com tornar-se terra na morte]; Polyb. 31, 10, 4; Ps.-Aristot., De Mundo 4 p. 394b, 8ff; PHib 5, 54 [III a.C.]; PGM 4, 538; 658; 2499; LXX; TestAbr A 17 p. 98, 19 [Stone p. 44] e outros; JosAs 19:3; SibOr 4, 46; Tat. 4:2) <span class=\"greek\">ἀφιέναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> entregar o espírito, expirar (Eur., Hec. 571; Porphyr., Vi. Plotini 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:50</a>. J emprega para isso <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. 19:3 (cf. ApcMos 31 <span class=\"greek\">ἀποδῶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>.; Just., D. 105, 5). Do retorno do espírito (vital) de uma pessoa falecida ao seu corpo morto: <span class=\"greek\">ἐπέστρεψεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:55</a> (cf. Jdg 15:19). <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖράς</span> <span class=\"greek\">σου</span> <span class=\"greek\">παρατίθεμαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μου</span> em tuas mãos confio meu espírito 23:46 (Ps 30:6; sobre a alegada ênfase em <span class=\"greek\">ἐλπίζειν</span>, v. EBons, BZ 38, ’94, 93–101). <span class=\"greek\">κύριε</span> <span class=\"greek\">Ἰησοῦ</span>, <span class=\"greek\">δέξαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμά</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.59\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:59</a>; combinação de ambas as passagens AcPl Ha 10, 23 (cf. ApcMos 42). <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεσπότης</span> <span class=\"greek\">δέξεται</span> GJs 23:3 (sobre o pneuma que voa para o alto após a morte, cf. Epicharm. em Vorsokrat. 23 [=13, 4ª ed.], B 9 e 22; Eur., Suppl. 533 <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αἰθέρα</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἐς</span> <span class=\"greek\">γῆν</span>; PGM 1, 177ff <span class=\"greek\">τελευτήσαντός</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">περιστελεῖ</span>, <span class=\"greek\">σοῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀέρα</span> <span class=\"greek\">ἄξει</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὑτῷ</span> ‘quando estiveres morto, [o anjo] envolverá teu corpo … e levará consigo teu espírito para o céu’). <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">πν</span>. <span class=\"greek\">νεκρόν</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:26</a>. <span class=\"greek\">πν</span>. <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰσῆλθεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> (isto é, os profetas-testemunhas que foram martirizados) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:11</a> (cf. Ezk 37:10 v.l. <span class=\"greek\">εἰσῆλθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ζωῆς</span>; v. 5). Do espírito que animou a imagem de uma besta e lhe possibilitou falar e fazer matar cristãos 13:15.—Após a morte de uma pessoa, o <span class=\"greek\">πν</span>. continua a viver como ser independente, no céu <span class=\"greek\">πνεύματα</span> <span class=\"greek\">δικαὶων</span> <span class=\"greek\">τετελειωμένων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:23</a> (cf. Da 3:86 <span class=\"greek\">εὐλογεῖτε</span>, <span class=\"greek\">πνεύματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ψυχαὶ</span> <span class=\"greek\">δικαίων</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>). Segundo fontes extrabíblicas, os <span class=\"greek\">πν</span>. estão no mundo inferior (cf. En 22:3–13; Sib Or 7, 127) ou no ar (PGM 1, 178), onde espíritos malignos podem impedi-los de subir mais alto (v. <span class=\"greek\">ἀήρ</span>2b). <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φυλακῇ</span> <span class=\"greek\">πνεύμασιν</span> <span class=\"greek\">πορευθεὶς</span> <span class=\"greek\">ἐκήρυξεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:19</a> pertence aqui se se refere à pregação de Jesus aos espíritos dos mortos confinados no Hades (assim Usteri et al.; v. também JMcCulloch, The Harrowing of Hell, 1930), quer quando desceu ao Hades, quer quando retornou ao céu (assim RBultmann, Bekenntnis u. Liedfragmente im 1 Pt: ConNeot11, ’47, 1–14).—CClemen, Niedergefahren zu den Toten 1900; JTurmel, La Descente du Christ aux enfers 1905; JMonnier, La Descente aux enfers 1906; HHoltzmann, ARW 11, 1908, 285–97; KGschwind, Die Niederfahrt Christi in die Unterwelt 1911; DPlooij, De Descensus in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:19</a> en 4:6: TT 47, 1913, 145–62; JBernard, The Descent into Hades a Christian Baptism (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:19ff</a>): Exp. 8ª série, 11, 1916, 241–74; CSchmidt, Gespräche Jesu mit seinen Jüngern: TU 43, 1919, 452ff; JFrings, BZ 17, 1926, 75–88; JKroll, Gott u. Hölle ’32; RGanschinietz, Katabasis: Pauly-W. X/2, 1919, 2359–449; Clemen2 89–96; WBieder, Die Vorstellung v. d. Höllenfahrt Jesu Chr. ’49; SJohnson, JBL 79, ’60, 48–51; WDalton, Christ’s Proclamation to the Spirits ’65. V. também a bibliografia em Windisch, Hdb.2 1930, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a>; ESelwyn, The First Ep. of St. Peter ’46 e 4c abaixo.—Provavelmente também cabe aqui <span class=\"greek\">θανατωθεὶς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ζωοποιηθεὶς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πνεύματι</span>· <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καὶ</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:18f</a> (alguns mss. leem <span class=\"greek\">πνεύματι</span> em vez de <span class=\"greek\">πνεύμασιν</span> no v. 19, evidentemente em referência ao modo de deslocamento de Jesus; <span class=\"greek\">πνεῦμα</span> é aquela parte de Cristo que, em contraste com <span class=\"greek\">σάρξ</span>, não pereceu na morte, mas subsistiu como entidade individual após a morte; v. <span class=\"greek\">ἐν</span> 7). Igualmente o contraste <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:3f</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>.</p><p class=\"entry-text\">③ Uma parte da personalidade humana, espírito.</p><p class=\"entry-text\">ⓐ Quando empregado com <span class=\"greek\">σάρξ</span>, a carne, denota a parte imaterial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a>. Carne e espírito=a personalidade inteira, em seus aspectos exterior e interior, frequentemente em Ign.: IMg 1:2; 13:1a; ITr ins; 12:1; IRo ins; ISm 1:1; IPol 5:1; AcPl Ant 13, 18 (=Aa I 237, 3).—No mesmo sentido ao lado de <span class=\"greek\">σῶμα</span>, o corpo (Simplicius, In Epict. p. 50, 1; Ps.-Phoc. 106f; PGM 1, 178) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:3</a>–5; 7:34.—A vida interior dos seres humanos divide-se em <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεῦμα</span> (cf. Ps.-Pla., Axioch. 10 p. 370c <span class=\"greek\">τὶ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">ἐνῆν</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>=um espírito divino estava efetivamente na alma; Wsd 15:11; Jos., Ant. 1, 34; Tat. 13, 2; 15, 1 et al.; Ath. 27, 1. V. também Herm. Wr. 10, 13; 16f; PGM 4, 627; 630. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">συνεστάναι</span> <span class=\"greek\">λέγουσι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span> Did., Gen. 55, 14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a> (v. GMilligan, Thess. 1908, 78f; EvDobschütz em Meyer X7 1909, 230ff; EBurton, Spirit, Soul, and Flesh 1918; AFestugière, La Trichotomie des <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a> et la Philos. gr.: RSR 20, 1930, 385–415; CMasson, RTP 33, ’45, 97–102; FGrant, An Introd. to NT Thought ’50, 161–66). <span class=\"greek\">σαρκί</span>, <span class=\"greek\">ψυχῇ</span>, <span class=\"greek\">πνεύματι</span> IPhld 11:2.</p><p class=\"entry-text\">ⓑ Como fonte e sede da compreensão, do sentimento e da vontade, geralmente como a parte representativa da vida interior humana (cf. PGM 4, 627; 3 Km 20:5; Sir 9:9 e outros; Just., D. 30, 1; Did., Gen. 232, 5) <span class=\"greek\">ἐπιγνοὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:8</a>. <span class=\"greek\">ἀναστενάξας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λέγει</span> 8:12 (v. <span class=\"greek\">ἀναστενάζω</span>). <span class=\"greek\">ἠγαλλίασεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:47</a> (em paralelismo com <span class=\"greek\">ψυχή</span> no v. 46, como Sir 9:9). <span class=\"greek\">ἠγαλλιάσατο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. 10:21 v.l., <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐνεβριμήσατο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:33</a> (v. <span class=\"greek\">ἐμβριμάομαι</span> 3); <span class=\"greek\">Ἰης</span>. <span class=\"greek\">ἐταράχθη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. 13:21. <span class=\"greek\">παρωξύνετο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:16</a>; <span class=\"greek\">ζέων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. com fervor de espírito 18:25 (v. <span class=\"greek\">ζέω</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">ἐκραταιοῦτο</span> <span class=\"greek\">πνεύματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:80</a>; 2:40 v.l.; <span class=\"greek\">ἔθετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. Paulo tomou uma resolução <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:21</a> (alguns colocariam esta passagem em 6c, mas cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:66</a> e formulações análogas de Hom. et al. em L-S-J-M s.v. <span class=\"greek\">τίθημι</span> A6). <span class=\"greek\">προσκυνήσουσιν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span>, da adoração espiritual, isto é, pura e interior, de Deus, que nada tem que ver com tempos, lugares, objetos ou cerimônias sagrados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:23</a>; cf. v. 24b. <span class=\"greek\">πν</span>. <span class=\"greek\">συντετριμμένον</span> (Ps 50:19) 1 Cl 18:17; 52:4.—2 Cl 20:4; Hv 3, 12, 2; 3, 13, 2.—Este emprego também se encontra em Paulo. Sua convicção (v. 5 abaixo) de que o cristão possui o <span class=\"greek\">πνεῦμα</span> (divino) e, por conseguinte, difere de todas as outras pessoas leva-o a preferir esta palavra a outras para caracterizar, de modo geral, o ser interior do crente. <span class=\"greek\">ᾧ</span> <span class=\"greek\">λατρεύω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:9</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔσχηκα</span> <span class=\"greek\">ἄνεσιν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:13</a>. Cf. 7:13. De fato, pode significar simplesmente o próprio eu de uma pessoa: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">συμμαρτυρεῖ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ἡμῶν</span> o Espírito (de Deus) dá testemunho juntamente com nosso próprio eu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:16</a> (cf. PGM 12, 327 <span class=\"greek\">ἠκούσθη</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">οὐρανοῦ</span>). <span class=\"greek\">ἀνέπαυσαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">πν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑμῶν</span> eles revigoraram tanto a mim como a vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:18</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πν</span>. (<span class=\"greek\">ὑμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:23</a>; Phlm 25. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:22</a>. Igualmente em Ign. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">πν</span>. meu próprio eu (indigno) IEph 18:1; IRo 9:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:11a</a>.—Sobre a relação do Espírito divino com o eu espiritual do crente, v. SWollenweider, Der Geist Gottes als Selbst der Glaubenden: ZTK 93, ’96, 163–92.—Apenas uma parte da vida interior, isto é, aquela que diz respeito à vontade, é significada em <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πρόθυμον</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">ἀσθενής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:38</a>; Pol 7:2. Aquilo que é inferior, a ansiedade, o medo do sofrimento etc., é atribuído à <span class=\"greek\">σάρξ</span>.—O sentido da expressão <span class=\"greek\">οἱ</span> <span class=\"greek\">πτωχοὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:3</a> é difícil de determinar com certeza (cf. Pla., Ep. 7, 335a <span class=\"greek\">πένης</span> <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>. O dat., como <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> M. Ant. 6, 52; 8, 51). O sentido provavelmente é: aqueles que são pobres em sua vida interior, porque não têm um orgulho mal orientado de suas próprias riquezas espirituais (v. AKlöpper, Über den Sinn u. die ursprgl. Form der ersten Seligpreisung der Bergpredigt bei Mt: ZWT 37, 1894, 175–91; RKabisch, Die erste Seligpreisung: StKr 69, 1896, 195–215; KKöhler, Die ursprgl. Form der Seligpreisungen: StKr 91, 1918, 157–92; JBoehmer, De Schatkamer 17, 1923, 11–16, TT [Copenhagen] 4, 1924, 195–207, JBL 45, 1926, 298–304; WMacgregor, ET 39, 1928, 293–97; VMacchioro, JR 12, ’32, 40–49; EEvans, Theology 47, ’44, 55–60; HLeisegang, Pneuma Hagion 1922, 134ff; Betz, SM 116 n. 178 para referências de Qumran).</p><p class=\"entry-text\">ⓒ Estado espiritual, estado de ânimo, disposição: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">πνεύματί</span> <span class=\"greek\">τε</span> <span class=\"greek\">πραΰτητος</span> com amor e espírito manso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοὸς</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:23</a> (v. <span class=\"greek\">νοῦς</span> 2a). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀφθάρτῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡσυχίου</span> <span class=\"greek\">πνεύματος</span> com o (dom) imperecível de uma disposição tranquila <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a>.</p><p class=\"entry-text\">④ Um ser incorpóreo independente, em contraste com um ser que pode ser percebido pelos sentidos físicos, espírito (ELangton, Good and Evil Spirits ’42).</p><p class=\"entry-text\">ⓐ Deus pessoalmente: <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:24a</a> (Ath. 16, 2; sobre Deus como espírito, especialmente na escola estoica, v. MPohlenz, D. Stoa ’48/49. Hdb. ad loc. Também Celsus 6, 71 [estoico]; Herm. Wr. 18, 3 <span class=\"greek\">ἀκάματον</span> <span class=\"greek\">μέν</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>).</p><p class=\"entry-text\">ⓑ Espíritos ou seres espirituais bons, ou pelo menos não expressamente malignos (cf. CIG III, 5858b <span class=\"greek\">δαίμονες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματα</span>; Proclus sobre Pla., Cratyl. p. 69, 6; 12 Pasqu.; En 15:4; 6; 8; 10; TestAbr A 4 p. 81, 15f [Stone p. 10, 15f] <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπουράνια</span> <span class=\"greek\">πνεύματα</span>; TestAbr B 13 p. 117, 26 [Stone p. 82] <span class=\"greek\">ὑψηλὸν</span> <span class=\"greek\">πν</span>.; PGM 3, 8 <span class=\"greek\">ἐπικαλοῦμαί</span> <span class=\"greek\">σε</span>, <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">πνεῦμα</span>; 4, 1448; 3080; 12, 249) <span class=\"greek\">πνεῦμα</span> com <span class=\"greek\">ἄγγελος</span> (cf. Jos., Ant. 4, 108; Ps.-Clem., Hom. 3, 33; 8, 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8f</a>. Deus é <span class=\"greek\">ὁ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">κτίστης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπίσκοπος</span> 1 Cl 59:3b.—Pl., Deus, o <span class=\"greek\">μόνος</span> <span class=\"greek\">εὐεργέτης</span> <span class=\"greek\">πνεύματων</span> 1 Cl 59:3a. Cf. 64 (sobre isso, v. Num 16:22; 27:16. Orações por vingança provenientes de Reneia [Dssm., LO 351–55=LAE 423ff=SIG 1181, 2] <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span>; PGM 5, 467 <span class=\"greek\">θεὸς</span> <span class=\"greek\">θεῶν</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πν</span>.; semelhantemente o papiro mágico PWarr 21, 24; 26 [III d.C.]); o <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>. Seres intermediários (na terminologia politeísta: <span class=\"greek\">δαίμονες</span>) que servem a Deus são chamados <span class=\"greek\">λειτουργικὰ</span> <span class=\"greek\">πνεύματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a>. Em Rv lemos acerca dos <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">πνεύματα</span> (<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) 1:4; 3:1; 4:5; 5:6; v. ASkrinjar, Biblica 16, ’35, 1–24; 113–40.—Fantasma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:37</a>, 39.</p><p class=\"entry-text\">ⓒ Espíritos malignos (PGM 13, 798; 36, 160; TestJob 27, 2; ApcSed [ambos Satanás]; AscIs 3:28; Just., D. 39, 6 e outros; Ath. 25, 3), especialmente nos relatos de cura dos Sinóticos: (<span class=\"greek\">τὸ</span>) <span class=\"greek\">πνεῦμα</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ἀκάθαρτον</span> (Just., D. 82, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:23</a>, 26; 3:30; 5:2, 8; 7:25; 9:25a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:29</a>; 9:42; 11:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:2</a>. Pl. (TestBenj 5:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a>; 3:11; 5:13; 6:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:36</a>; 6:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:16</a>; 8:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:13</a>; final de Mk no ms. Freer.—<span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:15f</a>. Pl. (En 99:7; TestSim 4:9; 6:6, TestJud 16:1; Just., D. 76, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:21</a>; 8:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:12f</a>.—<span class=\"greek\">πν</span>. <span class=\"greek\">ἄλαλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:17</a>; cf. v. 25b (v. <span class=\"greek\">ἄλαλος</span>). <span class=\"greek\">πν</span>. <span class=\"greek\">πύθων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a> (v. <span class=\"greek\">πύθων</span>). <span class=\"greek\">πν</span>. <span class=\"greek\">ἀσθενείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1b</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">δαιμονίου</span> <span class=\"greek\">ἀκαθάρτου</span> (v. <span class=\"greek\">δαιμόνιον</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:33</a>. <span class=\"greek\">πνεύματα</span> <span class=\"greek\">δαιμονίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:14</a> (na prática = ‘exalações’ personificadas de poderes malignos; para a combinação de <span class=\"greek\">πν</span>. e <span class=\"greek\">δαιμ</span>., cf. o encantamento amoroso Sb 4324, 16f <span class=\"greek\">τὰ</span> <span class=\"greek\">πνεύματα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμόνων</span> <span class=\"greek\">τούτων</span>).—Uso absoluto, de um espírito nocivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:18</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:16</a>; 12:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:20</a>; 11:26.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:19</a> (v. 2 acima) pertence aqui se <span class=\"greek\">πνεύματα</span> se refere a poderes espirituais hostis, espíritos malignos, anjos caídos (assim FSpitta, Christi Predigt an die Geister 1890; HGunkel, Zum religionsgesch. Verständnis des NT 1903, 72f; WBousset, ZNW 19, 1920, 50–66; Rtzst., Herr der Grösse 1919, 25ff; Knopf, Windisch, FHauck ad loc.; BReicke, The Disobedient Spirits and Christian Baptism ’46, especialmente 54–56, 69).—Hermas também apresenta a concepção de espíritos malignos que têm existência independente e vivem e reinam na vida interior de uma pessoa; o Espírito Santo, que também vive ou gostaria de viver ali, é expulso por eles (cf. TestDan 4) Hm 5, 1, 2–4; 5, 2, 5–8; 10, 1, 2. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> … <span class=\"greek\">ἕτερον</span> <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">πν</span>. 5, 1, 2. Esses <span class=\"greek\">πνεύματα</span> são <span class=\"greek\">ὀξυχολία</span> 5, 1, 3; 5, 2, 8 (<span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρότατον</span> <span class=\"greek\">πν</span>.); 10, 1, 2; <span class=\"greek\">διψυχία</span> 9:11 (<span class=\"greek\">ἐπίγειον</span> <span class=\"greek\">πν</span>. <span class=\"greek\">ἐστι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>); 10, 1, 2; <span class=\"greek\">λύπη</span> 10, 1, 2 (<span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span> <span class=\"greek\">πονηροτέρα</span>) e outros vícios. Sobre a complexa concepção de pneuma nos Mandamentos de Hermas, v. MDibelius, Hdb. excurso sobre Hm 5, 2, 7; cf. Leutzsch, Hermas 453f n. 133.</p><p class=\"entry-text\">⑤ O ser de Deus como influência governante, com ênfase na relação com os seres humanos, Espírito, espírito como aquilo que distingue Deus de tudo o que não é Deus, como o poder divino que produz toda existência divina, como o elemento divino no qual transcorre toda vida divina, como o portador de toda aplicação da vontade divina. Todos os que pertencem a Deus possuem ou recebem esse espírito e, por conseguinte, participam da vida de Deus. Esse espírito serve também para distinguir os cristãos de todos os incrédulos (cf. PGM 4, 1121ff, onde o espírito é saudado como aquele que entra nos devotos e, de acordo com a vontade de Deus, os separa de si mesmos, isto é, da parte puramente humana de sua natureza); sobre este último aspecto, v. especialmente 6 abaixo.</p><p class=\"entry-text\">ⓐ O Espírito de Deus, do Senhor (=Deus) etc. (LXX; TestSim 4:4; JosAs 8:11; ApcSed 14:6; 15:6; ApcMos 43; SibOr 3, 701; Ps.-Phoc. 106; Philo; Joseph. [v. c abaixo]; apologistas. Cf. Plut., Numa 4, 6 <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">θεοῦ</span>, capaz de gerar filhos; v. <span class=\"greek\">παρθένος</span> a) <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:11b</a>, 14; 3:16; 6:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:2a</a> (Just., D. 49, 3; Tat. 13, 3; Ath. 22, 3). <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:14</a> (Just., A I, 60, 6). <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:12b</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:9</a>; B 6:14; B 9:2 (cf. Mel., P. 32, 222). <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμά</span> <span class=\"greek\">μου</span> ou <span class=\"greek\">αὐτοῦ</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> (Is 42:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17f</a> (Jo 3:1f.—Cf. 1QS 4:21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:10a</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:8</a> (onde se acrescenta <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:13</a>.—<span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:20</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐγείραντος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:11a</a>.—Sem o artigo, <span class=\"greek\">πν</span>. <span class=\"greek\">θεοῦ</span> (JosAs 4:9; Tat. 15:3; Theoph. Ant. 1, 5 [p. 66, 18]) o Espírito de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; 12:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9b</a>, 14, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:40</a>; 12:3a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:3</a> (<span class=\"greek\">πν</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3</a>. <span class=\"greek\">πν</span>. <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:18</a> (Is 61:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a> (assim como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>; 20:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4</a>, esta passagem situa-se no limite entre os sentidos ‘vento’ e ‘espírito’; cf. Diod S 3, 60, 3 <span class=\"greek\">Ἕσπερον</span> <span class=\"greek\">ἐξαίφνης</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνευμάτων</span> <span class=\"greek\">συναρπαγέντα</span> <span class=\"greek\">μεγάλων</span> <span class=\"greek\">ἄφαντον</span> <span class=\"greek\">γενέσθαι</span> ‘Héspero [um filho de Atlas] foi subitamente arrebatado por ventos fortes e desapareceu de vista’. V. HLeisegang, Der Hl. Geist I 1, 1919, 19ff; OCullmann, TZ. 4, ’48, 364); 1 Cl 21:2.</p><p class=\"entry-text\">ⓑ O Espírito de Cristo, do Senhor (=Cristo) etc. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:7</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">Χριστοῦ</span> AcPlCor 2:32. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">πν</span>. <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a>. <span class=\"greek\">πν</span>. <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9c</a>. <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> AcPl Ha 8, 18. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστοῦ</span> AcPlCor 2:10. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">Ἰης</span>. <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:19</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:17b</a> (JHermann, Kyrios und Pneuma, ’61). <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">θεοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:6</a>. Como possuidor do Espírito divino e, ao mesmo tempo, aquele que governa sua distribuição entre os seres humanos, Cristo é chamado <span class=\"greek\">κύριος</span> <span class=\"greek\">πνεύματος</span> Senhor do Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:18</a> (v. Windisch ad loc.); mas muitos preferem traduzir: da parte do Senhor, que é o Espírito.—CMoule, OCullmann Festschr., ’72, 231–37.</p><p class=\"entry-text\">ⓒ Em razão de sua origem e natureza celestiais, este Espírito é chamado (o) Espírito Santo (cf. PGM 4, 510 <span class=\"greek\">ἵνα</span> <span class=\"greek\">πνεύσῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">πνεῦμα</span>.—Nem Fílon nem Josefo chamavam o Espírito de <span class=\"greek\">πν</span>. <span class=\"greek\">ἅγιον</span>; o primeiro empregava <span class=\"greek\">θεῖον</span> ou <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πν</span>., o segundo <span class=\"greek\">πν</span>. <span class=\"greek\">θεῖον</span>: Ant. 4, 118; 8, 408; 10, 239; mas <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span> Orig. C. Cels 1, 40, 16).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com o artigo, <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> (Is 63:10f; Ps 50:13; 142:10 v.l.; cf. Sus 45 Theod.; TestAbr A 4 p. 81, 10 [Stone p. 10]; JosAs 8:11 [codd. ADE]; AscIs 3, 15, 26; Just., D. 36, 6 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:32</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:29</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:10</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span>; sobre o ‘pecado contra o Espírito Santo’, v. HLeisegang, Pneuma Hagion 1922, 96–112; AFridrichsen, Le péché contre le Saint-Esprit: RHPR 3, 1923, 367–72). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a>; 13:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:26</a>; 3:22; 10:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>; 2:33; 5:3, 32; 7:51; 8:18 v.l.; 10:44, 47; 11:15; 13:2; 15:8, 28; 19:6; 20:23, 28; 21:11; 28:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span>); 4:30 (<span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:7</a>; 9:8; 10:15; 1 Cl 13:1; 16:2; 18:11 (Ps 50:13); 22:1; IEph 9:1; Hs 5, 5, 2; 5, 6, 5–7 (sobre a relação do Espírito Santo com o Filho em Hermas, v. ALink, Christi Person u. Werk im Hirten des Hermas 1886; JvWalter, ZNW 14, 1913, 133–44; MDibelius, Hdb. excurso após Hs 5, 6, 8 p. 572–76).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span> (Wsd 9:17; OdeSol 11:2; TestJob 51:2; ApcEsdr 7:16; Just. D. 25, 1 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:10</a> (v. acima), 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a>; 2:38 (gen. epexegético); 4:31; 9:31; 10:45; 13:4; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:7</a> v.l. (sobre o Comma Johanneum, v. <span class=\"greek\">λόγο</span> 3); GJs 24:4 (v. <span class=\"greek\">χρηματίζω</span> 1b<span class=\"greek\">α</span>). Como mãe de Jesus GHb 20, 61 (HLeisegang, Pneuma Hagion 1922, 64ff; SHirsch, D. Vorstellg. v. e. weibl. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγ</span>. im NT u. in d. ältesten christl. Lit. 1927. Também WBousset, Hauptprobleme der Gnosis 1907, 9ff).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sem o artigo (v. B-D-F §257, 2; Rob. 761; 795) <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγιον</span> (PGM 3, 289; Da 5:12 LXX; PsSol 17:37; AssMos Fgm. b; Just., D. 4, 1 e outros; Ath. 24, 1. V. também Da Theod. 4:8, 9, 18 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγιον</span> ou <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἅγιον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a>, 35, 41, 67; 2:25; 4:1; 11:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:22</a> (Cassien, La pentecôte johannique [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a>–23] ’39.—V. também 1QS 4:20f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4a</a>; 4:8; 7:55; 8:15, 17, 19; 9:17; 10:38; 11:24; 13:9; 19:2ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>; 6:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:12</a> v.l.; 1 Cl 2:2; AcPl 6:18; 9:4 (restaurado segundo Aa I 110, 11); AcPlCor 2:5.—Assim, frequentemente, em combinação com uma preposição: <span class=\"greek\">διὰ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:2</a>; 4:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:14</a>; 1 Cl 8:1 (cf. <span class=\"greek\">διὰ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">αἰωνίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:14</a>). <span class=\"greek\">διὰ</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">πν</span>. <span class=\"greek\">ἁγίου</span> AcPl Ha 11, 6. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> (Eus., PE 3, 12, 3, acerca dos egípcios: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">οἴονται</span> <span class=\"greek\">συλλαμβάνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">γῦπα</span>. Aqui <span class=\"greek\">πνεῦμα</span>=‘vento’; v. Horapollo 1, 11 p. 14f. O mesmo acerca de outras aves desde Aristot.—Sobre o neutro <span class=\"greek\">πνεῦμα</span> como princípio masculino, cf. Aristoxenus, Fgm. 13, acerca dos dois princípios originários: <span class=\"greek\">πατέρα</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">φῶς</span>, <span class=\"greek\">μητέρα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σκότος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>, 20; IEph 18:2; GJs 14:2; 19:1 (pap). <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ἁγίῳ</span> (PsSol 17:37; ApcZeph; Ar. 15, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:8</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:5</a> (cf. 1QS 3:7f); 11:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:1</a>; 14:17; 15:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:3b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:12</a> (sem <span class=\"greek\">ἐν</span> v.l.); Jd 20. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:21</a>. Cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:13</a>, 19 v.l. (em lugar de <span class=\"greek\">πνεύματος</span> <span class=\"greek\">θεοῦ</span>). <span class=\"greek\">μετὰ</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:6</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">ἀνακαινώσεως</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a>.</p><p class=\"entry-text\">ⓓ Em uso absoluto.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com o artigo, <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>. Neste contexto, o artigo talvez seja empregado por vezes anaforicamente, na segunda menção de uma palavra (v. B-D-F §252; Rob. 762); talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:31</a> (remetendo ao v. 28 <span class=\"greek\">πν</span>. <span class=\"greek\">θεοῦ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a>, 12 (cf. v. 8 <span class=\"greek\">πν</span>. <span class=\"greek\">ἅγιον</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:1b</a>, 14 (cf. v. 1a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4b</a> (cf. v. 4a).—Em regra, não é possível pressupor a presença de anáfora: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32</a>, 33a; 3:6a, 8b (em jogo de palavras), 34; 7:39a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:29</a>; 10:19; 11:12, 28; 19:1 D; 20:3 D, 22; 21:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:23</a> (<span class=\"greek\">ἀπαρχή</span> 1b<span class=\"greek\">β</span>; 2), 26a, 27; 12:11; 15:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:22</a> e 5:5 (KErlemann, ZNW 83, ’92, 202–23, e v. <span class=\"greek\">ἀρραβών</span>); 12:18 (<span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πν</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:2</a>, 5, 14 (<span class=\"greek\">ἐπαγγελία</span> 1b<span class=\"greek\">β</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:3</a> (gen. de autor); 6:17 (talvez gen. epexegético); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:24</a>; 5:6ab (alguns mss. acrescentam <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span> às palavras <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αἵματος</span> no início do versículo; isso é aprovado por HvSoden, Moffatt, Vogels, Merk e, com reservas, por CDodd, The Joh. Epistles ’46, TManson, JTS 48, ’47, 25–33), v. 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:7</a>, 11, 17, 29; 3:6, 13, 22; 14:13; 22:17; B 19:2, B 7= D 4:10 (v. <span class=\"greek\">ἐτοιμάζω</span> b). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> (conduzido) pelo Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:27</a>.—Paulo vincula esse Espírito de Deus, conhecido de todo cristão, a Cristo como agente libertador, em contraste com a restrição legal: <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐστιν</span> o Senhor significa Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:17a</a> (UHolzmeister, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:17</a> Dominus autem Spiritus est 1908; JNisius, Zur Erklärung v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:16ff</a>: ZKT 40, 1916, 617–75; JKögel, <span class=\"greek\">Ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμά</span> <span class=\"greek\">ἐστιν</span>: ASchlatter Festschr. 1922, 35–46; C Guignebert, Congr. d’Hist. du Christ. II 1928, 7–22; EFuchs, Christus u. d. Geist b. Pls ’32; HHughes, ET 45, ’34, 235f; CLattey, Verb. Dom. 20, ’40, 187–89; DGriffiths ET 55, ’43, 81–83; HIngo, Kyrios und Pneuma, ’61 [Paulo]; JDunn, JTS 21, ’70, 309–20).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sem o artigo, <span class=\"greek\">πνεῦμα</span> B 1:3. <span class=\"greek\">κοινωνία</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:1</a> (<span class=\"greek\">κοινωνία</span> 1 e 2). <span class=\"greek\">πνεύματι</span> no Espírito ou por meio do Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:3</a>; 5:5, 16, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:6</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">ζῶμεν</span> <span class=\"greek\">πνεύματι</span>, <span class=\"greek\">πνεύματι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">στοιχῶμεν</span> se vivemos pelo Espírito, andemos também pelo Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:25</a>. Frequentemente empregado com uma preposição: <span class=\"greek\">διὰ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:22</a> v.l. <span class=\"greek\">ἐξ</span> (<span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span>) <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:5</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> no Espírito, pelo Espírito, por meio do Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:22</a>; 3:5; 5:18; 6:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:8</a> (<span class=\"greek\">ἀγάπη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> amor suscitado pelo Espírito); B 9:7. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:29</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγιασμῷ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:2</a> (v. <span class=\"greek\">ἁγιασμός</span>).—Em expressões negativas: <span class=\"greek\">οὔπω</span> <span class=\"greek\">ἧν</span> <span class=\"greek\">πνεῦμα</span> o Espírito ainda não havia vindo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:39b</a>. <span class=\"greek\">ψυχικοὶ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχοντες</span> pessoas mundanas que não possuem o Espírito Jd 19.—<span class=\"greek\">ἓν</span> <span class=\"greek\">πνεῦμα</span> um só e mesmo Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:18</a>; 4:4; um (em) Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:17</a>.</p><p class=\"entry-text\">ⓔ O Espírito é definido mais precisamente por um gen. de coisa: <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> (TestJud 20:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:17</a>; 15:26; 16:13 (nessas três passagens, o Espírito da Verdade é o Paráclito prometido por Jesus por ocasião de sua partida); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:6</a> (oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span>, como TestJud 20:1; PsSol 8:14 <span class=\"greek\">πλ</span>. <span class=\"greek\">πλανήσεως</span>; Just., D. 7, 3 <span class=\"greek\">πλάνου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκαθάρτου</span> <span class=\"greek\">πνεύματος</span>; cf. 1QS 4:23); <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:14</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> o Espírito da vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:2</a>. <span class=\"greek\">το</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:13</a>. <span class=\"greek\">πν</span>. <span class=\"greek\">σοφίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποκαλύψεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:17</a> (cf. Just., D. 87, 4). <span class=\"greek\">πν</span>. <span class=\"greek\">υἱοθεσίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15b</a> (oposto a <span class=\"greek\">πν</span>. <span class=\"greek\">δουλείας</span> v. 15a). <span class=\"greek\">πν</span>. <span class=\"greek\">δυνάμεως</span> AcPl Ha 8, 25. <span class=\"greek\">πν</span>. <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωφρονισμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:7</a> (oposto a <span class=\"greek\">πν</span>. <span class=\"greek\">δειλίας</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> (v. TestJud 24:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a> (Zech 12:10); cf. 1 Cl 46:6.</p><p class=\"entry-text\">ⓕ Acerca de Cristo, ‘está escrito’ na Escritura: (<span class=\"greek\">ἐγένετο</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔσχατος</span> <span class=\"greek\">Ἀδὰμ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ζῳοποιοῦν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:45</a>. A passagem da Escritura em que se baseia a primeira parte deste versículo é Gen 2:7, onde Wsd 15:11 também emprega as palavras <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ζωτικόν</span> em lugar de <span class=\"greek\">πνοὴν</span> <span class=\"greek\">ζωῆς</span> (cf. Just., D. 6, 2). Por outro lado, v. Philo, Leg. All. 1, 42 e a bibliografia s.v. <span class=\"greek\">Ἀδάμ</span> ad loc.</p><p class=\"entry-text\">ⓖ O Pneuma (divino) contrapõe-se a tudo aquilo que caracteriza esta era ou o mundo finito em geral: <span class=\"greek\">οὐ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:2</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1ab</a>.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em contraste com <span class=\"greek\">σάρξ</span>, que está mais estreitamente ligada ao pecado do que qualquer outra matéria terrena (Just., D. 135, 6): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>–6, 9a, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:3</a>; 5:17ab; 6:8. Cf. B 10:9. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἐπιθυμία</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">στρατεύεται</span> Pol 5:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em contraste com <span class=\"greek\">σῶμα</span> (=<span class=\"greek\">σάρξ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:10</a> e com <span class=\"greek\">σάρξ</span> (=<span class=\"greek\">σῶμα</span>, como muitos sustentam) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63a</a> (para <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῳοποιοῦν</span> cf. Philo, Op. Mund. 30; Herm. Wr. em Cyrill., C. Jul. I 556c=542, 24 Sc., o pneuma <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ζῳοποιεῖ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρέφει</span>. V. também f acima). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:11b</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em contraste com <span class=\"greek\">γράμμα</span>, que é a qualidade característica da declaração anterior de Deus acerca da vontade divina na lei: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:29</a>; 7:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:6ab</a>, 8 (cf. v. 7).</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Em contraste com a sabedoria dos seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:13</a>.</p><p class=\"entry-text\">⑥ O Espírito de Deus conforme se manifesta no caráter ou na atividade do povo de Deus ou de agentes escolhidos, Espírito, espírito (v. HPreisker, Geist u. Leben ’33).</p><p class=\"entry-text\">ⓐ <span class=\"greek\">πνεῦμα</span> é acompanhado de outro substantivo, que caracteriza mais precisamente a atuação do Espírito: <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δύναμις</span> espírito e poder <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζωή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:63b</a>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σοφία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:3</a>; cf. v. 10 (cf. TestReub 2:6 <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">λαλίας</span>). <span class=\"greek\">πίστις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγιον</span> 6:5 (cf. Just., D. 135, 6). <span class=\"greek\">χαρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγ</span>. 13:52.</p><p class=\"entry-text\">ⓑ A menos que seja contrariado pelos seres humanos em sua condição natural, o Espírito de Deus produz um tipo espiritual de conduta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:16</a>, 25 e produz o <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> v. 22 (v. Vögtle sob <span class=\"greek\">πλεονεξία</span>).</p><p class=\"entry-text\">ⓒ O Espírito inspira determinadas pessoas de Deus B 12:2; B 13:5, sobretudo em sua condição de proclamadores de uma revelação divina (Strabo 9, 3, 5, o <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐνθουσιαστικόν</span>, que inspirava a Pítia; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 13, 2; 33, 5, acerca do <span class=\"greek\">πν</span>. divino que impele profetas e poetas a se expressarem; escol. sobre Pla. 856e, acerca de um <span class=\"greek\">μάντις</span>: <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληροῦσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Aristobulus em Eus., PE 8, 10, 4 [=Fgm. 2, 4 p. 136 Holladay] <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">πν</span>., <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">ἀνακεκήρυκται</span> ‘[Moisés possuía] o Espírito divino, de modo que foi proclamado profeta’; AscIs 1:7 <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">λαλοῦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>; AssMos Fgm. f <span class=\"greek\">εἶδεν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ἐπαρθείς</span>; Just., A I, 38, 1 e outros; Ath. 10, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">προφητικὸν</span> <span class=\"greek\">πν</span>. Cf. Marinus, Vi. Procli 23, acerca de Proclo: <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἄνευ</span> <span class=\"greek\">θείας</span> <span class=\"greek\">ἐπινοίας</span> … <span class=\"greek\">διαλέγεσθαι</span>; Orig., C. Cels. 3, 28, 23). <span class=\"greek\">προφητεία</span> somente veio à existência quando <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">φερόμενοι</span> <span class=\"greek\">ἐλάλησαν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἄνθρωποι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> v.l.; cf. 1 Cl 8:1. Davi <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>; 4:25. Isaías <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a>. Moisés B 10:2, B 9; o Espírito também atuou na entrega das tábuas da lei a Moisés 14:2. O próprio Cristo falou no AT <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> 1 Cl 22:1. As <span class=\"greek\">ἱεραὶ</span> <span class=\"greek\">γραφαί</span> são chamadas <span class=\"greek\">αἱ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> 45:2.—Também o profeta cristão Ágabo <span class=\"greek\">ἐσήμαινεν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:11</a>. Igualmente Ign. IPhld 7:2. Em geral, o Espírito revela os segredos mais profundos aos que creem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:10ab</a>.—1 Cl declara ter sido escrita <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγ</span>. <span class=\"greek\">πν</span>. 63:2. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:21</a>, v. 3b.</p><p class=\"entry-text\">ⓓ O Espírito de Deus, sendo um, manifesta a variedade e a riqueza de sua vida nos diferentes tipos de dons espirituais concedidos a determinados cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:4</a>, 7, 11; cf. v. 13ab.—Os vv. 8–10 enumeram os dons individuais do Espírito, empregando diversas preposições: <span class=\"greek\">διὰ</span> <span class=\"greek\">τοὺ</span> <span class=\"greek\">πν</span>. v. 8a; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. v. 8b; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πν</span>. v. 9ab. <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μὴ</span> <span class=\"greek\">σβέννυτε</span> não extingais o Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:19</a> refere-se ao dom de profecia, segundo o v. 20.—O emprego do pl. <span class=\"greek\">πνεύματα</span> explica-se em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:12</a> pela natureza variada da atuação do Espírito; no v. 32, pelo número de pessoas que possuem o espírito profético; sobre este último caso, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:6</a> e 19:10.</p><p class=\"entry-text\">ⓔ Um tipo especial de dom espiritual é representado pela fala extática. Daqueles que ‘falam em línguas’ que nenhuma pessoa terrena pode compreender: <span class=\"greek\">πνεύματι</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">μυστήρια</span> expressa coisas secretas de maneira espiritual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:2</a>. Cf. vv. 14–16 e v. <span class=\"greek\">νοῦς</span> 1b. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὑπερεντυγχάνει</span> <span class=\"greek\">στεναγμοῖς</span> <span class=\"greek\">ἀλαλήτοις</span> o Espírito intercede por nós com gemidos inexprimíveis por palavras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:26b</a>. Da fala que é extática, mas expressa em palavras compreensíveis, <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> D 11:7, 8; cf. v. 9 (sobre o assunto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:3</a>; Jos., Ant. 4, 118f; TestJob 43:2 <span class=\"greek\">ἀναλαβὼν</span> <span class=\"greek\">Ἐλιφᾶς</span> <span class=\"greek\">πν</span>. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ὕμνον</span>). Do estado de ânimo do vidente do Apocalipse: <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:3</a>; 21:10; <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πν</span>. 1:10; 4:2 (v. <span class=\"greek\">γίνομαι</span> 5c, <span class=\"greek\">ἐν</span> 4c e EMoering, StKr 92, 1920, 148–54; RJeske, NTS 31, ’85, 452–66); AcPl Ha 6, 27. Sobre o Espírito no Pentecostes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4</a>, v. KLake: Beginn. I 5, ’33, 111–21. <span class=\"greek\">κατασταλέντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Μύρτῃ</span> quando o Espírito (de profecia) que estava em Mirta cessou de falar AcPl Ha 7, 9.</p><p class=\"entry-text\">ⓕ O Espírito conduz e dirige os missionários cristãos em suas viagens (Aelian, NA 11, 16, as jovens são conduzidas de olhos vendados à caverna da serpente sagrada; são guiadas por um <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">θεῖον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:6</a>, 7 (por sonhos, entre outros meios; cf. v. 9f e v. Marinus, Vi. Procli 27: Proclo <span class=\"greek\">ἔφασκεν</span> <span class=\"greek\">προθυμηθῆναι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πολλάκις</span> <span class=\"greek\">γράψαι</span>, <span class=\"greek\">κωλυθῆναι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐναργῶς</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινων</span> <span class=\"greek\">ἐνυπνίων</span>). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:6</a>–7 distinguem-se <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πν</span>. e <span class=\"greek\">τὸ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">Ἰησοῦ</span>.</p><p class=\"entry-text\">⑦ Um espírito que impele à ação e que não procede de Deus, espírito: <span class=\"greek\">πν</span>. <span class=\"greek\">ἔτερον</span> um (tipo de) espírito diferente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:1</a>–3. Por haver pessoas movidas por tais espíritos, é necessário provar os vários tipos de espíritos (o mesmo problema Artem. 3, 20 <span class=\"greek\">περὶ</span> <span class=\"greek\">διαφορᾶς</span> <span class=\"greek\">μάντεων</span>, <span class=\"greek\">οἷς</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">προσέχειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">μή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:1b</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span> <span class=\"greek\">πληροῖ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πν</span>. Hm 11:3. Também <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἴδατε</span> <span class=\"greek\">ποίου</span> <span class=\"greek\">πνεύματός</span> <span class=\"greek\">ἐστε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:55</a> v.l. distingue entre o espírito manifestado pelos discípulos de Jesus e outro tipo de espírito.—Mais raramente ainda, um espírito concedido por Deus que não é o próprio Espírito de Deus; assim (em uma citação de Is 29:10) um <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κατανύξεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:8</a>.</p><p class=\"entry-text\">⑧ Uma personalidade transcendente independente, o Espírito, que aparece em fórmulas que se tornaram cada vez mais fixas e distintas (cf. Ath. 12, 2; Hippol., Ref. 7, 26, 2.—Ps.-Lucian, Philopatr. 12 <span class=\"greek\">θεόν</span>, <span class=\"greek\">υἱόν</span> <span class=\"greek\">πατρός</span>, <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἐκπορευόμενον</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">τρία</span>, <span class=\"greek\">ταῦτα</span> <span class=\"greek\">νόμιζε</span> <span class=\"greek\">Ζῆνα</span>, <span class=\"greek\">τόνδ</span>’ <span class=\"greek\">ἡγοῦ</span> <span class=\"greek\">θεόν</span>=‘Deus, filho do pai, espírito que procede do pai, um de três e três de um, considera estes como Zeus, considera este como Deus’. Todo o contexto traz a marca cristã.—Como Éon na especulação gnóstica Iren. 1, 2, 5 [Harv. I 21, 2]): <span class=\"greek\">βαπτίζοντες</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:19</a> (sobre o texto, v. <span class=\"greek\">βαπτίζω</span> 2c; sobre o assunto, GWalther, Die Entstehung des Taufsymbols aus dem Taufritus: StKr 95, 1924, 256ff); D 7:1, 3. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:13</a>; 1 Cl 58:2; IEph 9:1; IMg 13:1b, 2; MPol 14:3; 22:1, 3; Epil Mosq 5. Sobre isso, v. HUsener, Dreiheit: RhM 58, 1903, 1ff; 161ff; 321ff; especialmente 36ff; EvDobschütz, Zwei-u. dreigliedrige Formeln: JBL 50, ’31, 116–47 (também Heinrici Festschr. 1914, 92–100); Norden, Agn. Th. 228ff; JMainz, Die Bed. der Dreizahl im Judentum 1922; Clemen2 125–28; NSöderblom, Vater, Sohn u. Geist 1909; DNielsen, Der dreieinige Gott I 1922; GKrüger, Das Dogma v. der Dreieinigkeit 1905, 46ff; AHarnack, Entstehung u. Entwicklung der Kirchenverfassung 1910, 187ff; JHaussleiter, Trinitarischer Glaube u. Christusbekenntnis in der alten Kirche: BFCT XXV 4, 1920; JLebreton, Histoire du dogme de la Trinité I: Les origines6 1927; RBlümel, Pls u. d. dreieinige Gott 1929.—Sobre o vocábulo em seu conjunto, FRüsche, D. Seelenpneuma ’33; HLeisegang, Der Hl. Geist I 1, 1919; EBurton, ICC Gal 1921, 486–95; PVolz, Der Geist Gottes u. d. verwandten Erscheinungen im AT 1910; JHehn, Zum Problem des Geistes im alten Orient u. im AT: ZAW n.s. 2, 1925, 210–25; SLinder, Studier till Gamla Testamentets föreställningar om anden 1926; AMarmorstein, Der Hl. Geist in der rabb. Legende: ARW 28, 1930, 286–303; NSnaith, The Distinctive Ideas of the OT ’46, 229–37; FDillistone, Bibl. Doctrine of the Holy Spirit: Theology Today 3, ’46/47, 486–97; TNicklin, Gospel Gleanings ’50, 341–46; ESchweizer, CDodd Festschr., ’56, 482–508; DLys, Rûach, Le Souffle dans l’AT, ’62; DHill, Gk. Words and Hebr. Mngs. ’67, 202–93.—HGunkel, Die Wirkungen des Hl. Geistes2 1899; HWeinel, Die Wirkungen des Geistes u. der Geister im nachap. Zeitalter 1899; EWinstanley, The Spirit in the NT 1908; HSwete, The Holy Spirit in the NT 1909, The Holy Spirit in the Ancient Church 1912; EScott, The Spirit in the NT 1923; FBüchsel, Der Geist Gottes im NT 1926; EvDobschütz, Der Geistbesitz des Christen im Urchristentum: Monatsschr. für Pastoral-theol. 20, 1924, 228ff; FBadcock, ‘The Spirit’ and Spirit in the NT: ET 45, ’34, 218–21; RBultmann, Theologie des NT ’48, 151–62 (trad. inglesa KGrobel, ’51, I 153–64); ESchweizer, Geist u. Gemeinde im NT ’52, Int 6, ’52, 259–78.—WTosetti, Der Hl. Geist als göttliche Pers. in den Evangelien 1918; HLeisegang, Pneuma Hagion. Der Ursprung des Geistbegriffs der Syn. Ev. aus der griech. Mystik 1922; AFrövig, Das Sendungsbewusstsein Jesu u. der Geist 1924; HWindisch, Jes. u. d. Geist nach Syn. Überl.: Studies in Early Christianity, presented to FCPorter and BWBacon 1928, 209–36; FSynge, The Holy Spirit in the Gospels and Acts: CQR 120, ’35, 205–17; CBarrett, The Holy Spirit and the Gospel Trad. ’47.—ESokolowski, Die Begriffe Geist u. Leben bei Pls 1903; KDeissner, Auferstehungshoffnung u. Pneumagedanke bei Pls 1912; GVos, The Eschatological Aspect of the Pauline Conception of the Spirit: Bibl. and Theol. Studies by the Faculty of Princeton Theol. Sem. 1912, 209–59; HBertrams, Das Wesen des Geistes nach d. Anschauung des Ap. Pls 1913; WReinhard, Das Wirken des Hl. Geistes im Menschen nach den Briefen des Ap. Pls 1918; HHoyle, The Holy Spirit in St. Paul 1928; PGächter, Z. Pneumabegriff des hl. Pls: ZKT 53, 1929, 345–408; ASchweitzer, D. Mystik des Ap. Pls 1930, 159–74 e outros [Mysticism of Paul the Apostle, trad. WMontgomery ’31, 160–76 e outros]; E-BAllo, RB 43, ’34, 321–46 [1 Cor]; Ltzm., Hdb. excurso após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:11</a>; Synge [v. acima], CQR 119, ’35, 79–93 [epístolas paulinas]; NWaaning, Onderzoek naar het gebruik van <span class=\"greek\">πνεῦμα</span> bij Pls, diss. Amsterd. ’39; RJewett, Paul’s Anthropological Terms, ’71, 167–200.—HvBaer, Der Hl. Geist in den Lukasschriften 1926; MGoguel, La Notion joh. de l’Esprit 1902; JSimpson, The Holy Spirit in the Fourth Gospel: Exp., 9ª série, 4, 1925, 292–99; HWindisch, Jes. u. d. Geist im J.: Amicitiae Corolla (RHarris Festschr.) ’33, 303–18; WLofthouse, The Holy Spirit in Ac and J: ET 52, ’40/41, 334–36; CBarrett, The Holy Spirit in the Fourth Gospel: JTS 1 n.s., ’50, 1–15; FCrump, Pneuma in the Gospels, diss. Catholic Univ. of America, ’54; GLampe, Studies in the Gospels (RHLightfoot memorial vol.) ’55, 159–200; NHamilton, The Holy Spirit and Eschatology in Paul, ’57; WDavies, Paul and the Dead Sea Scrolls, Flesh and Spirit: The Scrolls and the NT, ed. KStendahl, ’57, 157–82.—GJohnston, ‘Spirit’ and ‘Holy Spirit’ in the Qumran Lit.: NT Sidelights (ACPurdy Festschr.) ’60, 27–42; JPryke, ‘Spirit’ and ‘Flesh’ in Qumran and NT, RevQ 5, ’65, 346–60; HBraun, Qumran und d. NT II, ’66, 150–64; DHill, Greek Words and Hebrew Meanings, ’67, 202–93; WBieder, Pneumatolog. Aspekte im Hb, OCullmann Festschr. ’72, 251–59; KEasley, The Pauline Usage of <span class=\"greek\">πνεύματι</span> as a Reference to the Spirit of God: JETS 27, ’84, 299–313 (estatísticas).—B. 260; 1087. Pauly-W. XIV 387–412. BHHW I 534–37. Schmidt, Syn. II 218–50. New Docs 4, 38f. DELG s.v. <span class=\"greek\">πνέω</span>. M-M. Dict. de la Bible XI 126–398. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνευματικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πνεῦμα</span>; Pre-Socr. et al., principalmente no sentido ‘relativo ao vento ou ao sopro’; Strabo 1, 3, 5; Cleom. [II d.C.] 1, 8 p. 84, 22; Vett. Val. p. 1, 11; 231, 20; PLond I, 46, 25 p. 66 [IV d.C.?]; PGM 5, 25; GrBar 13:4 [<span class=\"greek\">π</span>. <span class=\"greek\">πατέρας</span>]; Philo; Just.; Tat. 15, 3), predominantemente em Paulo em nossa literatura (alhures somente 1 Pt, 2 Cl, B, Ign., D).</p><p class=\"entry-text\">① Relativo ao espírito como vida interior de um ser humano, espiritual (v. <span class=\"greek\">πνεῦμα</span> 3.—Plut., Mor. 129c <span class=\"greek\">πν</span>. contrapõe-se a <span class=\"greek\">σωματικόν</span>; Hierocles 27, 483 <span class=\"greek\">τὸ</span> <span class=\"greek\">πνευματικὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ὄχημα</span>=o veículo espiritual da alma; cf. também Philo, Rer. Div. Her. 242); assim talvez <span class=\"greek\">ἐπιμελείᾳ</span> <span class=\"greek\">σαρκικῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνευματικῆ</span> IPol 1:2 (v. <span class=\"greek\">ἐπιμέλεια</span>); cf. 2:2; IMg 13:2; ISm 12:2; 13:2. Mas o sentido 2a não é improvável.</p><p class=\"entry-text\">② Na grande maioria dos casos em referência ao <span class=\"greek\">πνεῦμα</span> divino (v. <span class=\"greek\">πνεῦμα</span> 5), relativo ao espírito (divino), causado pelo espírito (divino) ou cheio dele, pertinente/correspondente ao espírito (divino) (Philo, Abr. 113; PGM 4, 1778; Zosimus [2a<span class=\"greek\">γ</span> abaixo, fim]).</p><p class=\"entry-text\">ⓐ Adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De Jesus; em sua preexistência 2 Cl 14:2. <span class=\"greek\">σαρκικός</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνευματικός</span> de carne e (ao mesmo tempo) de espírito IEph 7:2. Do <span class=\"greek\">δεύτερος</span> <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:47</a> P46 (v. também o acréscimo <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em regra, é empregado acerca de coisas impessoais (<span class=\"greek\">πλήρωμα</span> Iren. 1, 1, 3 [Harv. I 11, 11]; <span class=\"greek\">νόμος</span> Orig., C. Cels. 4, 1, 28; <span class=\"greek\">βρῶμα</span> 2, 2, 50; <span class=\"greek\">ἀρετή</span> Did., Gen. 236, 6): a lei dada por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:14</a>. <span class=\"greek\">χάρισμα</span> <span class=\"greek\">πν</span>. 1:11. <span class=\"greek\">τῆς</span> <span class=\"greek\">δωρεᾶς</span> <span class=\"greek\">πνευματικῆς</span> <span class=\"greek\">χάριν</span> B 1:2 (v. <span class=\"greek\">δωρεά</span>). <span class=\"greek\">εὐλογία</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a> (v. <span class=\"greek\">εὐλογία</span> 3b<span class=\"greek\">α</span>). <span class=\"greek\">ᾠδαὶ</span> <span class=\"greek\">πν</span>. cânticos espirituais 5:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:16</a> (cf. Just., D. 118, 2 <span class=\"greek\">πν</span>. <span class=\"greek\">αἴνους</span>). <span class=\"greek\">σύνεσις</span> <span class=\"greek\">πν</span>. entendimento dado pelo Espírito 1:9. Os cristãos devem deixar-se edificar como <span class=\"greek\">οἶκος</span> <span class=\"greek\">πν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:5a</a> e devem oferecer <span class=\"greek\">πν</span>. <span class=\"greek\">θυσίαι</span> v. 5b (ESelwyn, 1 Pt ’46, 281–85). Empregando a mesma figura, B 16:10 caracteriza o crente como <span class=\"greek\">πν</span>. <span class=\"greek\">ναός</span>. Ign. chama suas cadeias de <span class=\"greek\">πν</span>. <span class=\"greek\">μαργαρῖται</span> IEph 11:2; a comunhão que o une ao bispo de Éfeso é <span class=\"greek\">συνήθεια</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνθρωπίνη</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πνευματική</span> 5:1; ao presbitério chama <span class=\"greek\">ἀξιόπλοκος</span> <span class=\"greek\">πνευματικὸς</span> <span class=\"greek\">στέφανος</span> uma coroa espiritual dignamente entretecida IMg 13:1.—Da Ceia do Senhor e de seu correspondente no AT: <span class=\"greek\">πνευματικὸν</span> <span class=\"greek\">βρῶμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:3</a> e <span class=\"greek\">πν</span>. <span class=\"greek\">πόμα</span> v. 4a, o primeiro no maná concedido do céu (v. <span class=\"greek\">βρῶμα</span> 1), o segundo na água <span class=\"greek\">ἐκ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">πέτρας</span> v. 4b (v. <span class=\"greek\">πέτρα</span> 1a). <span class=\"greek\">πνευματικὴ</span> <span class=\"greek\">τροφὴ</span> <span class=\"greek\">καὶ</span> (sc. <span class=\"greek\">πνευματικὸν</span>) <span class=\"greek\">ποτόν</span> D 10:3.—Aquilo que pertence à ordem transcendente do ser é descrito como <span class=\"greek\">πν</span>.: assim, o corpo da ressurreição é um <span class=\"greek\">σῶμα</span> <span class=\"greek\">πν</span>. (a expressão: Cleopatra p. 24 linha 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:44a</a>; cf. v. 44b. Da igreja preexistente 2 Cl 14:1, 2, 3.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πνευματικὸς</span> (subentendendo-se <span class=\"greek\">ἄνθρωπος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:15</a> contrapõe-se a <span class=\"greek\">ψυχικὸς</span> <span class=\"greek\">ἄνθρωπος</span> do v. 14. Este último é uma pessoa que não possui mais do que uma alma humana comum; o primeiro possui o <span class=\"greek\">πνεῦμα</span> divino, não ao lado de sua alma humana natural, mas em lugar dela; isso capacita a pessoa a penetrar os mistérios divinos. Esse tratamento de <span class=\"greek\">ψυχή</span> e <span class=\"greek\">πνεῦμα</span> em contraste entre si também se encontra na mística helenística (v. Rtzst., Mysterienrel.3 70f; 325ff; 333ff; JWeiss, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:44a</a>. V. também Zosimus em CALG parte 2, 230 <span class=\"greek\">οὐ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πνευματικὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπιγνόντα</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">κτλ</span>.=Hermetica IV p. 105, 25 Sc.; v. também p. 107, 7. Iren. 1, 8, 3 [Harv. I 72, 6].—HMüller, Plotinos u. der Ap. Pls: Her 54, 1919, 109f).</p><p class=\"entry-text\">ⓑ Substantivado.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Neut. <span class=\"greek\">τὰ</span> <span class=\"greek\">πνευματικά</span> coisas ou assuntos espirituais (em contraste com <span class=\"greek\">τὰ</span> <span class=\"greek\">σαρκικά</span> coisas terrenas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:11</a>; é característico dos adeptos da sã tradição, assim como <span class=\"greek\">τὰ</span> <span class=\"greek\">σαρκ</span>. o é dos dissidentes IEph 8:2 (v. <span class=\"greek\">β</span> abaixo).—<span class=\"greek\">τὰ</span> <span class=\"greek\">πν</span>. dons espirituais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:1</a> (o gen. aqui também pode ser masc.: aqueles que possuem dons espirituais); 14:1. Em <span class=\"greek\">πνευματικοῖς</span> <span class=\"greek\">πνευματικὰ</span> <span class=\"greek\">συγκρίνοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:13</a> o dat. deve ser entendido quer como neut. (Lghtf., BWeiss, Bachmann, Ltzm., Rtzst. op. cit. 336, H-DWendland), quer como masc. (Schmiedel, Heinrici, JWeiss, Sickenberger); v. <span class=\"greek\">συγκρίνω</span> e <span class=\"greek\">πνευματικῶς</span> 2.—<span class=\"greek\">τὸ</span> <span class=\"greek\">πνευματικόν</span> (em contraste com <span class=\"greek\">τὸ</span> <span class=\"greek\">ψυχικόν</span> [v. 2a<span class=\"greek\">γ</span> acima]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:46</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Masc. (<span class=\"greek\">ὁ</span>) <span class=\"greek\">πνευματικός</span> que possui o Espírito, aquele que possui o Espírito (com <span class=\"greek\">προφήτης</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:37</a>. (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πνευματικοί</span> (<span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πν</span>. <span class=\"greek\">μόνοι</span> Hippol., Ref. 5, 9, 6) (as) pessoas cheias do Espírito 3:1 (oposto a <span class=\"greek\">σάρκινοι</span> e <span class=\"greek\">νήπιοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>; B 4:11; IEph 8:2 (dos adeptos da sã tradição em contraste com <span class=\"greek\">σαρκικοί</span>, dissidentes; v. 2b<span class=\"greek\">α</span> acima). Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:13</a> e 12:1 (2b<span class=\"greek\">α</span>).</p><p class=\"entry-text\">③ Relativo a espíritos (malignos) (v. <span class=\"greek\">πνεῦμα</span> 4c), substantivado: <span class=\"greek\">τὰ</span> <span class=\"greek\">πνευματικὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span> as forças espirituais do mal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a>.—DELG s.v. <span class=\"greek\">πνέω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματικῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνευματικῶς</span>, adv. de <span class=\"greek\">πνευματικός</span> (Hermogenes [II d.C.], Inv. 4, 1 no sentido ‘num só fôlego’, v. L-S-J-M).</p><p class=\"entry-text\">① Relativo à influência transcendente, espiritualmente, de maneira espiritual, de maneira causada pelo Espírito ou impregnada dele, em referência à vida interior de uma pessoa (v. <span class=\"greek\">πνευματικός</span> 1): <span class=\"greek\">μένετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">σαρκικῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνευματικῶς</span> permanecei em Jesus Cristo tanto no corpo como no espírito, isto é, com toda a personalidade (v. <span class=\"greek\">πνεῦμα</span> 3a) IEph 10:3. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνάστασιν</span> <span class=\"greek\">συνέφαγεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">σαρκικὸς</span> <span class=\"greek\">καίπερ</span> <span class=\"greek\">πνευματικῶς</span> <span class=\"greek\">ἡνωμένος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span> após sua ressurreição comeu com eles como se estivesse no corpo, embora unido espiritualmente ao Pai ISm 3:3 assinala a transição para</p><p class=\"entry-text\">② Relativo à conformidade com a influência transcendente, de acordo com o espírito, em referência ao <span class=\"greek\">πνεῦμα</span> divino (v. <span class=\"greek\">πνευματικός</span> 2): <span class=\"greek\">πνευματικῶς</span> <span class=\"greek\">ἀνακρίνεται</span> deve ser examinado de maneira condizente com o Espírito (divino) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:14</a>.—O v. 13 (v. <span class=\"greek\">πνευματικός</span> 2b<span class=\"greek\">α</span>) apresenta <span class=\"greek\">πνευματικῶς</span> como v.l. de <span class=\"greek\">πνευματικοῖς</span>. Diz-se de Paulo, quando escreveu 1 Cor, que <span class=\"greek\">πνευματικῶς</span> <span class=\"greek\">ἐπέστειλεν</span> <span class=\"greek\">ὑμῖν</span> cheio do Espírito (divino), escreveu-vos 1 Cl 47:3.—Cabe aqui também <span class=\"greek\">ἥτις</span> (isto é, a cidade de Jerusalém) <span class=\"greek\">καλεῖται</span> <span class=\"greek\">πνευματικῶς</span> <span class=\"greek\">Σόδομα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>: se se segue a compreensão espiritual (o oposto é <span class=\"greek\">σαρκικῶς</span> Just., D. 14, 2) da Escritura (cf. Is 1:9f), Jerusalém está oculta sob o nome Sodoma. Está implicado aqui algo mais do que simples alegoria ou emprego figurado.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματοφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνευματοφόρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πνεῦμα</span>, <span class=\"greek\">φέρω</span>; sobre formações semelhantes, v. Hdb. Ergänzungsband 189–91 sobre <span class=\"greek\">Θεοφόρος</span>; Schwyzer I 438f; para uma lista detalhada, v. CBuck, Reverse Index ’44, 335f), que traz em si o Espírito (divino), substantivado (Herm. Wr. 13, 19), portador do Espírito, dos profetas cristãos Hm 11:16 (adj. dos profetas do AT Hos 9:7; Zeph 3:4; Leutzsch, Hermas 464 n. 271; v. também Lampe s.v.—Cf. DELG s.v. <span class=\"greek\">φέρω</span> D.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνέω</span> fut. 3ª pess. sing. <span class=\"greek\">πνεύσει</span> LXX; 1º aor. <span class=\"greek\">ἔπνευσα</span> (Hom. et al.; pap, LXX; En 29:2; TestSol; ApcSed 8:9 p. 133, 14 Ja.; Philo, Joseph.)</p><p class=\"entry-text\">① Mover-se como vento com movimento relativamente rápido, soprar, uso absoluto (Hom. et al.; Ptolem., Apotel. 1, 11, 4 <span class=\"greek\">οἱ</span> <span class=\"greek\">πνέοντες</span> <span class=\"greek\">ἄνεμοι</span>; PHib 27, 59; Sir 43:20; EpJer 60; ApcSed 8:9; Jos., Bell. 7, 318, Ant. 7, 76; SibOr 5, 375) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a> (Diod S 24, 1, 2 <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πνεύσαντοσ</span>=quando soprou um vento); 6:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:1</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνέμῳ</span> <span class=\"greek\">ἐπιδόντες</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνέοντι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:15</a> v.l.—Substantivado: <span class=\"greek\">ἡ</span> <span class=\"greek\">πνέουσα</span> (subentenda-se <span class=\"greek\">αὔρα</span>; esta palavra é acrescentada por Arrian, Peripl. 3, 2), o vento que soprava (Lucian [<span class=\"greek\">ἐπιδίδωμι</span> 2]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:40</a>.</p><p class=\"entry-text\">② Emitir um odor, exalar, uso absoluto, <span class=\"greek\">ὠς</span> <span class=\"greek\">λιβανωτοῦ</span> <span class=\"greek\">πνέοντος</span> MPol 15:2.</p><p class=\"entry-text\">③ Com ac. (Hom. et al.; escol. sobre Nicander, Ther. 308 <span class=\"greek\">δυσωδίαν</span> <span class=\"greek\">πνεοντες</span>; 2 Macc 9:7; En 29:2), exalar algo. A unção de Jesus tinha por finalidade <span class=\"greek\">ἵνα</span> <span class=\"greek\">πνέῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> <span class=\"greek\">ἀφθαρσίαν</span> para que soprasse imortalidade sobre a igreja e, portanto, para dentro dela IEph 17:1 (sobre <span class=\"greek\">πνέω</span> <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>=‘infundir algo em alguém’, cf. Ps.-Clem., Hom. 4, 19).—B. 260, 684. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνίγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνίγω</span> imperf. <span class=\"greek\">ἔπνιγον</span>; 1º aor. <span class=\"greek\">ἔπνιξα</span> (Trag., Hdt.+; ChronLind B, 111; PTebt 278, 40; 1 Km 16:14f; TestSol; Jos., Bell. 2, 327, Ant. 10, 121).</p><p class=\"entry-text\">① Exercer pressão ao redor do pescoço a fim de matar, estrangular (desde Sophron Com. [V a.C.] 68; Pla., Gorg. 522a; cf. Vett. Val. 127, 1; 1 Km 16:14), em narrativa dramática <span class=\"greek\">κρατήσας</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἔπνιγεν</span> agarrou-o e começou a estrangulá-lo (=agarrou-o de modo a sufocá-lo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:28</a> (Lucian, Dial. Mort. 22, 2 emprega o sinônimo <span class=\"greek\">ἄγχω</span> para o tratamento de um devedor).</p><p class=\"entry-text\">② Fazer com que algo seja sufocado, sufocar.</p><p class=\"entry-text\">ⓐ A ira sufoca o Espírito Santo no interior da personalidade humana: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> … <span class=\"greek\">πνίγεται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span> <span class=\"greek\">πνεύματος</span> Hm 5, 1, 3 (cf. 1 Km 16:14f).</p><p class=\"entry-text\">ⓑ De ervas daninhas em relação à boa semente, sufocar (X., Oec. 17, 14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:7</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀμπελὼν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">βοτάνας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πνιγούσας</span> <span class=\"greek\">αὐτόν</span> a vinha sem as ervas daninhas que a sufocavam Hs 5, 2, 4b; cf. ibid. a.</p><p class=\"entry-text\">ⓒ Pass. ser sufocado, intr. sufocar-se (Themistocl., Ep. 12), afogar-se (X., An. 5, 7, 25; Plut., Mor. 599b; Jos., Ant. 10, 121; 20, 248) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:13</a>.</p><p class=\"entry-text\">ⓓ Fig. (Lysippus Com. [V a.C.], Fgm. 7, 9 [I p. 702 Kock] <span class=\"greek\">πνίγομαι</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοῖσ</span>=sufoco-me de repugnância por eles) <span class=\"greek\">πνίγεσθαι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πράξεων</span> ser sufocado pelo próprio trabalho Hs 9, 20, 2.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνικτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνικτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πνίγω</span>; no grego não bíblico somente com outro sentido: Pherecrates Com. [V a.C.] 175 e Alexis Com. 124, 2=‘cozido a vapor, guisado, assado’; Galen VI p. 707, 1 e outros. É restaurado numa inscrição do Asclepieion de Cós A 26f; 41 por RHerzog: ARW 10, 1907, 402; 408f.—Não ocorre na LXX nem nos escritos judaicos helenísticos), em Ac significa claramente estrangulado, morto por sufocação (assim também Ps.-Clem., Hom. 7, 8; 8, 19), de animais mortos sem que deles se tenha drenado o sangue, cuja carne era proibida aos israelitas comer (Lev 17:13f. A esse respeito Philo, Spec. Leg. 4, 122 opõe-se àqueles que estrangulam (<span class=\"greek\">ἄγχοντες</span>) e sufocam (<span class=\"greek\">ἀποπνίγοντες</span>) animais.—Hierocles 26, 480, as leis dietéticas pitagóricas proíbem <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀθύτων</span> <span class=\"greek\">σαρκῶν</span> <span class=\"greek\">μετάληψις</span>=participação de carne de animais que não foram devidamente abatidos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:20</a>, 29; 21:25 (D omite o termo nas três passagens).—Sobre as questões suscitadas por esta palavra, v. Harnack, SBBerlAk 1899, 150ff (=Studien I 1f) e, com outro resultado, em: Die Apostelgeschichte 1908, 189ff e Neue Untersuchungen zur AG 1911, 22ff; GResch, D. Aposteldekret: TU n.s. 13, 1905; ASeeberg, Die beiden Wege u. d. Aposteldekret 1906; HvanOort, TT 40, 1906, 97ff; HCoppieters, RB 4, 1907, 31ff; 218ff; WSanday, The Apostolic Decree, Acts 15:20–29: Theol. Studien, TZahn dargebr. 1908, 317–38, The Text of the Apost. Decr.: Exp. 8ª série, 6, 1913, 289–305; HDiehl, ZNW 10, 1909, 277–96; KLake, CQR 71, 1911, 345ff, Jew. Stud. in Mem. of IAbrahams 1927, 244ff, Beginn. I 5, ’33, nota 16, especialmente p. 206ff; KSix, Das Aposteldekret 1912; FDibelius, StKr 87, 1914, 618ff; AWikenhauser, Die AG 1921, 213ff; LBrun, Apostelkonzil u. Aposteldekret: NorTT 21, 1920, 1–52; JRopes, The Text of Acts (=Beginn. I 3) 1926, 265ff; HLietzmann, Amicitiae Corolla ’33, 203–11; HWaitz, D. Problem des sog. Aposteldekrets: ZKG 55, ’36, 227–63; MDibelius, D. Apostelkonzil: TLZ 72, ’47, 193–98; OCullmann, Petrus ’52, 47ff; WKümmel, KKundsin Festschr. ’53, 83ff; EHaenchen ad loc.; FBruce, Ac3 ’90 ad loc.—DELG s.v. <span class=\"greek\">πνίγω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνοή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πνοή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πνέω</span>)</p><p class=\"entry-text\">① Movimento relativamente rápido do ar, vento (Hom. et al.; Job 37:10; TestSol; GrBar 2:1; ApcEsdr 5:23 p. 30, 26 Tdf. ‘sopro do vento’; SibOr 5, 375 [<span class=\"greek\">πνοιή</span>]; Ar. 5, 4f [<span class=\"greek\">ἀνέμων</span>]) <span class=\"greek\">πν</span>. <span class=\"greek\">βιαία</span> um vento forte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2</a>.</p><p class=\"entry-text\">② O processo de respirar, respiração, alento (Trag. et al.; LXX; TestReub 2:5; JosAs [também de coisas: aroma 15:14 <span class=\"greek\">οἴνου</span>; 16:4 <span class=\"greek\">κηρίου</span> <span class=\"greek\">μέλιτος</span>]; GrBar 8:7), com <span class=\"greek\">ζωή</span> (cf. Gen 2:7; 7:22; Philo, Spec. Leg. 4, 123 <span class=\"greek\">πνοὴ</span> <span class=\"greek\">ζωῆς</span> e Pr 24:12 <span class=\"greek\">ὁ</span> <span class=\"greek\">πλάσας</span> <span class=\"greek\">πνοὴν</span> <span class=\"greek\">πᾶσιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:25</a> (v. TMitchell, The OT Usage of NeSama, VT 11, ’61, 177–87). Abstrato pelo concreto: <span class=\"greek\">πᾶσα</span> <span class=\"greek\">πν</span>. tudo o que respira (Ps 150:6; TestAbr A 13 p. 92, 17 [Stone p. 32]; GrBar 8:7) Pol 2:1. Passa ao sentido de <span class=\"greek\">πνεῦμα</span> (PGM 12, 331; 333; Ath. 7, 1), acerca da <span class=\"greek\">πνοή</span> de Deus 1 Cl 21:9 (Knopf, Hdb. ad loc.); 57:3 (Pr 1:23).—B. 260. DELG s.v. <span class=\"greek\">πνέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαπός</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποδαπός</span> v. <span class=\"greek\">ποταπός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδήρης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποδήρης</span>, <span class=\"greek\">ες</span> (<span class=\"greek\">πούς</span> ±<span class=\"greek\">ήρης</span> ‘ajustado’) que chega aos pés (Aeschyl. et al.; LXX; EpArist 96; Philo, Fuga 185), substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">ποδ</span>. (subentenda-se <span class=\"greek\">χιτών</span>; empregado com <span class=\"greek\">χιτών</span> X., Cyr. 6, 4, 2; Paus. 5, 19, 6; Ex 29:5; Jos., Ant. 3, 153. Sem <span class=\"greek\">χιτ</span>. Appian, Liby. 66 §296; Ex 25:7; 28:4; Ezk 9:3; EpArist 96; Philo, Leg. All. 2, 56; Jos., Bell. 5, 231; TestLevi 8:2), uma veste que chega aos pés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a>; B 7:9.—DELG s.v. <span class=\"greek\">πούς</span> e -<span class=\"greek\">ηρης</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδονιπτήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποδονιπτήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (Stesichorus 10D [188 Page] em Athen. 10, 451d; Plut., Mor. 151e; Phryn. 689 Lob.), bacia para lavar os pés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5</a> P66. Encontra-se mais comumente na grafia <span class=\"greek\">ποδανιπτήρ</span> (Hdt. 2, 172; Aristot., Pol. 1, 12 e outros; GDI 3340, 33 [Argólida]; SIG 1169, 33 [III a.C.]).—DELG s.v. <span class=\"greek\">νίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόθεν</h1><div class=\"entry-meta\"><span>advérbio interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόθεν</span>, adv. interrogativo (Hom.+), em perguntas diretas e indiretas: ‘de onde, de qual, donde’.</p><p class=\"entry-text\">① Expressão interrogativa de extensão a partir de uma origem local, de que lugar? de onde? (Hom. et al.; Gen 16:8; 29:4; Tob 7:3; Jos., Ant. 9, 211; 11, 210) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:4</a> (QQuesnell, The Mind of Mark ’69, 164–68); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:25</a>, 27 (2 Cl 4:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a> e semelhantemente IPhld 7:1 (v. EvdGoltz, Ign. v. Ant. 1894, 134–36); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:11</a>; talvez 6:5, mas v. 3 abaixo; 8:14ab (<span class=\"greek\">πόθεν</span> <span class=\"greek\">ἦλθον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">ὑπάγω</span>. V. GWetter, Eine gnost. Formel im vierten Ev.: ZNW 18, 1918, 49–63); 9:29f; 19:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:13</a>. <span class=\"greek\">πόθεν</span> <span class=\"greek\">αὕτη</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνή</span> de onde poderia ter vindo esta voz GJs 11:1.—Em linguagem figurada <span class=\"greek\">μνημόνευε</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">πέπτωκες</span> lembra-te de que (estado) caíste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>. <span class=\"greek\">γινώσκομεν</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐλυτρώθημεν</span> reconhecemos de que (estado) fomos resgatados B 14:7. <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐκλήθημεν</span> 2 Cl 1:2.</p><p class=\"entry-text\">② Expressão interrogativa de derivação a partir de uma origem, de que fonte? produzido ou dado por quem? nascido de quem? (Hom. et al.; Jos., Vi. 334; Just., A I, 29, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:27</a>, 54, 56; 21:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:1ab</a>; B 10:12; IEph 19:2; GJs 13:3. <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐστίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:27ab</a> poderia ser interpretado de acordo com 6:42 e então significaria de que espécie de pais nasceu. Mas um sentido mais geral também é provável.</p><p class=\"entry-text\">③ Expressão interrogativa de causa ou razão, como, por quê, de que maneira? (Aeschyl. et al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:37</a>. Em pergunta que exprime surpresa (ático; Jer 15:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:43</a>; GJs 12:2 (<span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐμοί</span> Plut., Mor. 526f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:48</a>; 6:5 (Field, Notes 91 ‘com quê’, v. 1). [<span class=\"greek\">π</span>]<span class=\"greek\">ό̣θ̣ε̣</span>[<span class=\"greek\">ν</span>] <span class=\"greek\">ἔ̣χαιτε</span> (=<span class=\"greek\">ἔχετε</span>) [<span class=\"greek\">το͂ν</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">τοῦτον</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πιστεύ</span>]<span class=\"greek\">ε̣τε</span> de onde tendes este rei, de modo que nele credes (=de onde vem vosso rei, para suscitar tamanho compromisso de vossa parte) AcPl Ha 9, 30f.—DELG s.v. <span class=\"greek\">πο</span>-. Frisk. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0290-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποθέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποθέω</span> (cognato de <span class=\"greek\">θέσσασθαι</span> ‘orar por’, v. Boisacq 342, 799; Schwyzer I 719), 1º aor. <span class=\"greek\">ἐπόθησα</span> (v. os dois artigos seguintes; Hom. et al.; LXX; TestSol 1:3 L; Test12Patr, Philo, Jos., Just., Mel.), ter forte desejo de, desejar, almejar, ansiar, empenhar-se por <span class=\"greek\">τὶ</span> algo (Pr 7:15; TestIss 2:5; SibOr 5, 420; Philo, De Jos. 90 <span class=\"greek\">ἀλήθειαν</span>; Jos., Ant. 2, 65; Just., A I, 5, 4; Mel., P. 38, 261) D 4:3 (codd. e Lake; Bihlmeyer e muitos editores <span class=\"greek\">ποιήσεις</span>, cf. B 19:12); Dg 10:1. Seguido do inf. aor. (Philo, Fuga 8 <span class=\"greek\">μαθεῖν</span>; Jos., Vi. 204; Just., D. 2, 3) B 16:10; Dg 3:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ποθούμενα</span> aquilo que é desejável aos olhos de Deus 12:8.—DELG.</p></section></article>"};
